1 | import { execSync } from 'child_process';
2 | import * as crypto from 'crypto';
3 | import * as path from 'path';
4 | import { ChangedFile, FileCategory } from '../models/types';
5 | 
6 | /**
7 |  * Git operations for commit detection and diff analysis.
8 |  */
9 | export class GitAnalyzer {
10 |   private repoPath: string;
11 | 
12 |   constructor(repoPath: string) {
13 |     this.repoPath = repoPath;
14 |   }
15 | 
16 |   /**
17 |    * Get current HEAD commit hash (short = 7 chars, long = 40 chars).
18 |    */
19 |   getHead(short = true): string {
20 |     try {
21 |       return execSync(`git rev-parse ${short ? '--short' : ''} HEAD`, {
22 |         cwd: this.repoPath,
23 |         encoding: 'utf8',
24 |         stdio: ['pipe', 'pipe', 'pipe'],
25 |       }).trim();
26 |     } catch {
27 |       return 'unknown';
28 |     }
29 |   }
30 | 
31 |   /**
32 |    * Get current branch name.
33 |    */
34 |   getBranch(): string {
35 |     try {
36 |       return execSync('git rev-parse --abbrev-ref HEAD', {
37 |         cwd: this.repoPath,
38 |         encoding: 'utf8',
39 |         stdio: ['pipe', 'pipe', 'pipe'],
40 |       }).trim();
41 |     } catch {
42 |       return 'main';
43 |     }
44 |   }
45 | 
46 |   /**
47 |    * Get list of changed files between two commits.
48 |    */
49 |   getChangedFiles(oldCommit: string, newCommit: string): ChangedFile[] {
50 |     try {
51 |       const output = execSync(`git diff --name-status ${oldCommit} ${newCommit}`, {
52 |         cwd: this.repoPath,
53 |         encoding: 'utf8',
54 |         stdio: ['pipe', 'pipe', 'pipe'],
55 |       }).trim();
56 | 
57 |       if (!output) return [];
58 | 
59 |       return output.split('\n').map(line => {
60 |         const [status, ...rest] = line.split('\t');
61 |         const filePath = rest[rest.length - 1];
62 |         const changeType = this.mapStatus(status);
63 |         const category = this.classifyFile(filePath);
64 |         return { path: filePath, category, changeType };
65 |       }).filter(f => f.path);
66 |     } catch {
67 |       return [];
68 |     }
69 |   }
70 | 
71 |   /**
72 |    * Get all Java files changed since a specific commit.
73 |    */
74 |   getChangedJavaFiles(oldCommit: string, newCommit: string): string[] {
75 |     return this.getChangedFiles(oldCommit, newCommit)
76 |       .filter(f => f.path.endsWith('.java'))
77 |       .map(f => f.path);
78 |   }
79 | 
80 |   /**
81 |    * Classify a file path into a category.
82 |    */
83 |   classifyFile(filePath: string): FileCategory {
84 |     const lower = filePath.toLowerCase();
85 |     const basename = path.basename(lower);
86 | 
87 |     // Spring Boot
88 |     if (basename.endsWith('controller.java')) return 'API';
89 |     if (lower.includes('/controller/')) return 'API';
90 |     if (basename.endsWith('entity.java')) return 'ENTITY';
91 |     if (lower.includes('/entity/') || lower.includes('/entities/')) return 'ENTITY';
92 |     if (lower.includes('/model/') || basename.endsWith('dto.java') || basename.endsWith('request.java') || basename.endsWith('response.java')) return 'DTO';
93 |     if (lower.includes('/service/') && basename.endsWith('service.java')) return 'SERVICE';
94 |     // F08: application.yaml should be CONFIG too
95 |     if (
96 |       basename === 'application.properties' ||
97 |       basename === 'application.yml' ||
98 |       basename === 'application.yaml' ||
99 |       basename === 'pom.xml'
100 |     ) return 'CONFIG';
101 |     if (basename.endsWith('.java')) return 'SERVICE';
102 | 
103 |     // Node.js / TypeScript
104 |     if (lower.includes('/routes/') || lower.includes('/controllers/') || basename.endsWith('.routes.ts') || basename.endsWith('.routes.js') || basename.endsWith('.controller.ts') || basename.endsWith('.controller.js')) return 'API';
105 |     if (basename === 'package.json') return 'CONFIG';
106 |     if (basename.endsWith('.ts') || basename.endsWith('.js') || basename.endsWith('.mjs')) return 'SERVICE';
107 | 
108 |     // Python
109 |     if (lower.includes('/routes/') || lower.includes('/views/') || basename.endsWith('_routes.py') || basename.endsWith('_views.py') || basename.endsWith('_api.py')) return 'API';
110 |     if (basename === 'requirements.txt' || basename === 'pyproject.toml' || basename === 'setup.py' || basename === 'setup.cfg') return 'CONFIG';
111 |     if (basename.endsWith('.py')) return 'SERVICE';
112 | 
113 |     // Go
114 |     if (lower.includes('/handlers/') || lower.includes('/routes/') || basename.endsWith('_handler.go') || basename.endsWith('_routes.go')) return 'API';
115 |     if (basename === 'go.mod' || basename === 'go.sum') return 'CONFIG';
116 |     if (basename.endsWith('.go')) return 'SERVICE';
117 | 
118 |     return 'UNKNOWN';
119 |   }
120 | 
121 |   private mapStatus(status: string): 'added' | 'modified' | 'deleted' {
122 |     if (status.startsWith('A')) return 'added';
123 |     if (status.startsWith('D')) return 'deleted';
124 |     return 'modified';
125 |   }
126 | 
127 |   /**
128 |    * Get git log for recent commits.
129 |    */
130 |   getRecentCommits(count = 10): Array<{ hash: string; message: string; author: string; date: string }> {
131 |     try {
132 |       const output = execSync(`git log --oneline -${count} --format="%H|%s|%an|%ai"`, {
133 |         cwd: this.repoPath,
134 |         encoding: 'utf8',
135 |         stdio: ['pipe', 'pipe', 'pipe'],
136 |       }).trim();
137 | 
138 |       return output.split('\n').filter(Boolean).map(line => {
139 |         const [hash, message, author, date] = line.split('|');
140 |         return { hash, message, author, date };
141 |       });
142 |     } catch {
143 |       return [];
144 |     }
145 |   }
146 | 
147 |   /**
148 |    * Check if given commit hash is valid.
149 |    */
150 |   isValidCommit(hash: string): boolean {
151 |     try {
152 |       execSync(`git rev-parse --verify ${hash}`, {
153 |         cwd: this.repoPath,
154 |         encoding: 'utf8',
155 |         stdio: ['pipe', 'pipe', 'pipe'],
156 |       });
157 |       return true;
158 |     } catch {
159 |       return false;
160 |     }
161 |   }
162 | 
163 |   /**
164 |    * Produce a short fingerprint of the current working-tree dirty state.
165 |    * Uses `git status --porcelain` (tracks staged + unstaged + untracked)
166 |    * plus a stat of changed file sizes so content edits are detected even
167 |    * when no commit has been made yet.
168 |    *
169 |    * Returns 'clean' when the working tree is identical to HEAD, or a
170 |    * short hex string when there are uncommitted modifications.
171 |    */
172 |   getDirtyHash(): string {
173 |     try {
174 |       // --porcelain=v1 gives a stable machine-readable format
175 |       const statusOutput = execSync('git status --porcelain=v1', {
176 |         cwd: this.repoPath,
177 |         encoding: 'utf8',
178 |         stdio: ['pipe', 'pipe', 'pipe'],
179 |       }).trim();
180 | 
181 |       if (!statusOutput) return 'clean';
182 | 
183 |       // Include a rough content fingerprint: sum of file sizes for modified files.
184 |       // This is cheap (no hashing of file contents) yet detects edits.
185 |       const lines = statusOutput.split('\n').filter(Boolean);
186 |       const fileParts: string[] = [];
187 |       for (const line of lines) {
188 |         // columns 0-1 = XY status codes, col 3+ = file path (rename: "old -> new")
189 |         const status = line.slice(0, 2).trim();
190 |         const filePath = line.slice(3).split(' -> ').pop()!.trim();
191 |         fileParts.push(`${status}:${filePath}`);
192 |       }
193 | 
194 |       const raw = fileParts.sort().join('\n');
195 |       return crypto.createHash('sha1').update(raw).digest('hex').slice(0, 12);
196 |     } catch {
197 |       return 'clean';
198 |     }
199 |   }
200 | 
201 |   /**
202 |    * Get the list of working-tree dirty files relative to HEAD.
203 |    * Returns ChangedFile entries for all staged + unstaged modifications,
204 |    * allowing incremental analysis against uncommitted edits.
205 |    */
206 |   getDirtyFiles(): ChangedFile[] {
207 |     try {
208 |       const output = execSync('git status --porcelain=v1', {
209 |         cwd: this.repoPath,
210 |         encoding: 'utf8',
211 |         stdio: ['pipe', 'pipe', 'pipe'],
212 |       }).trim();
213 | 
214 |       if (!output) return [];
215 | 
216 |       return output
217 |         .split('\n')
218 |         .filter(Boolean)
219 |         .map(line => {
220 |           const xy = line.slice(0, 2);
221 |           const rawPath = line.slice(3).split(' -> ').pop()!.trim();
222 |           const changeType = xy.includes('D') ? 'deleted' : xy.includes('A') || xy.trim() === '??' ? 'added' : 'modified';
223 |           return { path: rawPath, category: this.classifyFile(rawPath), changeType } as ChangedFile;
224 |         });
225 |     } catch {
226 |       return [];
227 |     }
228 |   }
229 | }
