5 | interface CacheMetadata {
6 |   lastAnalyzedCommit: string;
7 |   /** The dirty-tree hash at the time of the last analysis ('clean' when no uncommitted changes) */
8 |   lastDirtyHash: string;
9 |   /** F03: The commit that was indexed before the current HEAD (used as comparison baseline) */
10 |   baselineCommit: string | null;
11 |   previousCommit: string | null;
12 |   lastAnalyzedAt: string;
13 |   schemaVersion: number;
14 | }
15 | 
16 | const SCHEMA_VERSION = 3;
17 | 
18 | interface CacheIndex {
19 |   /** Fingerprint of workspace discovery topology (marker file paths+sizes) */
20 |   workspaceFingerprint?: string;
21 |   /** Cached list of discovered service IDs in workspace-fingerprint order */
22 |   discoveredServiceIds?: string[];
23 |   metadata: Record<string, CacheMetadata>;
24 | }
