26 | /**
27 |  * JSON file-based persistent cache for ServiceContext objects.
28 |  * Cache key: serviceId + branch + commitHash + dirtyHash
29 |  *
30 |  * The compound key lets uncommitted working-tree edits invalidate the cache
31 |  * without requiring a git commit:
32 |  *  - dirtyHash='clean'  → no uncommitted changes → keyed purely on commit
33 |  *  - dirtyHash=<hex>    → uncommitted changes present → separate cache slot
34 |  *
35 |  * A workspace fingerprint (hash of marker-file paths+sizes) is stored so
36 |  * the engine can skip the full filesystem re-discovery walk when the
37 |  * project structure hasn't changed.
38 |  */
39 | export class ContextCache {
40 |   private cacheDir: string;
41 |   private indexPath: string;
42 |   private index: CacheIndex;
43 | 
44 |   constructor(cacheDir: string) {
45 |     this.cacheDir = cacheDir;
46 |     fs.mkdirSync(cacheDir, { recursive: true });
47 |     this.indexPath = path.join(cacheDir, 'index.json');
48 |     this.index = this.loadIndex();
49 |   }
50 | 
51 |   private loadIndex(): CacheIndex {
52 |     try {
53 |       if (fs.existsSync(this.indexPath)) {
54 |         const parsed = JSON.parse(fs.readFileSync(this.indexPath, 'utf8')) as CacheIndex;
55 |         // Migrate old entries that lack schemaVersion / baselineCommit / lastDirtyHash
56 |         for (const [, meta] of Object.entries(parsed.metadata)) {
57 |           if (!('schemaVersion' in meta)) {
58 |             (meta as any).schemaVersion = 1;
59 |             (meta as any).baselineCommit = (meta as any).previousCommit ?? null;
60 |           }
61 |           if (!('lastDirtyHash' in meta)) {
62 |             (meta as any).lastDirtyHash = 'clean';
63 |           }
64 |         }
65 |         return parsed;
66 |       }
67 |     } catch {
68 |       // corrupt index — start fresh
69 |     }
70 |     return { metadata: {} };
71 |   }
72 | 
73 |   private saveIndex(): void {
74 |     try {
75 |       // Atomic write: write to temp then rename
76 |       const tmp = this.indexPath + '.tmp';
77 |       fs.writeFileSync(tmp, JSON.stringify(this.index, null, 2), 'utf8');
78 |       fs.renameSync(tmp, this.indexPath);
79 |     } catch {
80 |       // ignore write errors
81 |     }
82 |   }
83 | 
84 |   private contextFilePath(serviceId: string, branch: string, commitHash: string, dirtyHash = 'clean'): string {
85 |     // Safe filename: replace slashes in branch names
86 |     const safeBranch = branch.replace(/[/\\]/g, '_');
87 |     const dirtySuffix = dirtyHash !== 'clean' ? `_${dirtyHash}` : '';
88 |     return path.join(this.cacheDir, `${serviceId}_${safeBranch}_${commitHash}${dirtySuffix}.json`);
89 |   }
90 | 
91 |   /**
92 |    * Get cached context for a service at a specific commit + dirty state.
93 |    */
94 |   get(serviceId: string, branch: string, commitHash: string, dirtyHash = 'clean'): ServiceContext | null {
95 |     const filePath = this.contextFilePath(serviceId, branch, commitHash, dirtyHash);
96 |     try {
97 |       if (fs.existsSync(filePath)) {
98 |         return JSON.parse(fs.readFileSync(filePath, 'utf8')) as ServiceContext;
99 |       }
100 |     } catch {
101 |       // corrupt cache entry
102 |     }
103 |     return null;
104 |   }
105 | 
106 |   /**
107 |    * Store a ServiceContext in the cache.
108 |    * dirtyHash='clean' means it was analysed against the committed HEAD only.
109 |    */
110 |   set(context: ServiceContext, dirtyHash = 'clean'): void {
111 |     const { serviceId, branch, commitHash } = context.identity;
112 | 
113 |     // Write context file
114 |     const filePath = this.contextFilePath(serviceId, branch, commitHash, dirtyHash);
115 |     try {
116 |       const tmp = filePath + '.tmp';
117 |       fs.writeFileSync(tmp, JSON.stringify(context, null, 2), 'utf8');
118 |       fs.renameSync(tmp, filePath);
119 |     } catch {
120 |       return; // can't write cache
121 |     }
122 | 
123 |     // Reload index from disk before modifying to avoid lost updates (F11)
124 |     this.index = this.loadIndex();
125 | 
126 |     // Update metadata index — F03: track baselineCommit separately
127 |     const existing = this.index.metadata[serviceId];
128 |     const prevCommit = existing?.lastAnalyzedCommit ?? null;
129 |     this.index.metadata[serviceId] = {
130 |       lastAnalyzedCommit: commitHash,
131 |       lastDirtyHash: dirtyHash,
132 |       // baselineCommit: only advance when the commit actually changed
133 |       baselineCommit: prevCommit !== commitHash ? prevCommit : (existing?.baselineCommit ?? null),
134 |       previousCommit: prevCommit,
135 |       lastAnalyzedAt: new Date().toISOString(),
136 |       schemaVersion: SCHEMA_VERSION,
137 |     };
138 |     this.saveIndex();
139 |   }
140 | 
141 |   /**
142 |    * Get the last analyzed commit hash for a service.
143 |    */
144 |   getLastAnalyzedCommit(serviceId: string): string | null {
145 |     // Re-read index from disk so a concurrent writer's changes are visible (F11)
146 |     this.index = this.loadIndex();
147 |     return this.index.metadata[serviceId]?.lastAnalyzedCommit ?? null;
148 |   }
149 | 
150 |   /**
151 |    * Get the dirty hash that was current at the last analysis.
152 |    * 'clean' means no uncommitted changes were present during the last analysis.
153 |    */
154 |   getLastDirtyHash(serviceId: string): string {
155 |     this.index = this.loadIndex();
156 |     return this.index.metadata[serviceId]?.lastDirtyHash ?? 'clean';
157 |   }
158 | 
159 |   /**
160 |    * F03: Get the baseline commit for change comparison.
161 |    * This is the commit that was current BEFORE the latest index write.
162 |    */
163 |   getBaselineCommit(serviceId: string): string | null {
164 |     this.index = this.loadIndex();
165 |     return this.index.metadata[serviceId]?.baselineCommit ?? null;
166 |   }
167 | 
168 |   /**
169 |    * Get the previous commit (before the last analysis) for incremental diff.
170 |    */
171 |   getPreviousCommit(serviceId: string): string | null {
172 |     return this.index.metadata[serviceId]?.previousCommit ?? null;
173 |   }
174 | 
175 |   /**
176 |    * Check if we have a cached context for the current commit + dirty state.
177 |    */
178 |   isCached(serviceId: string, branch: string, commitHash: string, dirtyHash = 'clean'): boolean {
179 |     return this.get(serviceId, branch, commitHash, dirtyHash) !== null;
180 |   }
181 | 
182 |   // ── Workspace fingerprint ───────────────────────────────────────────────
183 | 
184 |   /**
185 |    * Store the workspace fingerprint (hash of marker-file topology) and the
186 |    * ordered list of discovered service IDs that goes with it. This lets the
187 |    * engine skip the full filesystem crawl on the next startup when the
188 |    * project structure hasn't changed.
189 |    */
190 |   setWorkspaceFingerprint(fingerprint: string, serviceIds: string[]): void {
191 |     this.index = this.loadIndex();
192 |     this.index.workspaceFingerprint = fingerprint;
193 |     this.index.discoveredServiceIds = serviceIds;
194 |     this.saveIndex();
195 |   }
196 | 
197 |   /**
198 |    * Returns { fingerprint, serviceIds } if a stored workspace fingerprint
199 |    * exists, or null if none is stored yet.
200 |    */
201 |   getWorkspaceFingerprint(): { fingerprint: string; serviceIds: string[] } | null {
202 |     this.index = this.loadIndex();
203 |     if (this.index.workspaceFingerprint && this.index.discoveredServiceIds) {
204 |       return {
205 |         fingerprint: this.index.workspaceFingerprint,
206 |         serviceIds: this.index.discoveredServiceIds,
207 |       };
208 |     }
209 |     return null;
210 |   }
211 | 
212 |   // ── Utility ─────────────────────────────────────────────────────────────
213 | 
214 |   /**
215 |    * List all cached service IDs with their latest commit info.
216 |    */
217 |   listCached(): Array<{ serviceId: string; commitHash: string; dirtyHash: string; analyzedAt: string }> {
218 |     return Object.entries(this.index.metadata).map(([serviceId, meta]) => ({
219 |       serviceId,
220 |       commitHash: meta.lastAnalyzedCommit,
221 |       dirtyHash: meta.lastDirtyHash,
222 |       analyzedAt: meta.lastAnalyzedAt,
223 |     }));
224 |   }
225 | 
226 |   /**
227 |    * Invalidate cache for a service.
228 |    */
229 |   invalidate(serviceId: string): void {
230 |     // Remove all cache files for this service
231 |     try {
232 |       const files = fs.readdirSync(this.cacheDir);
233 |       for (const file of files) {
234 |         if (file.startsWith(serviceId + '_')) {
235 |           fs.unlinkSync(path.join(this.cacheDir, file));
236 |         }
237 |       }
238 |     } catch {
239 |       // ignore
240 |     }
241 |     delete this.index.metadata[serviceId];
242 |     this.saveIndex();
243 |   }
244 | 
245 |   /**
246 |    * Estimate token savings based on context size.
247 |    */
248 |   estimateTokenSavings(context: ServiceContext): number {
249 |     const json = JSON.stringify(context);
250 |     // Rough estimate: 4 chars per token
251 |     return Math.floor(json.length / 4);
252 |   }
253 | 
254 |   close(): void {
255 |     // no-op for JSON cache — nothing to close
256 |   }
257 | }
