36 | /**
37 |  * Main orchestrator for the Bob Context Graph analysis pipeline.
38 |  * Coordinates discovery, caching, incremental analysis, and graph building.
39 |  *
40 |  * Compound cache key: serviceId + branch + commitHash + dirtyHash
41 |  *   - commitHash tracks committed changes (git HEAD)
42 |  *   - dirtyHash  tracks uncommitted working-tree edits (git status --porcelain)
43 |  *
44 |  * Workspace fingerprint: a hash of marker-file topology (pom.xml, package.json …).
45 |  * When it matches the stored value the service-discovery filesystem crawl is
46 |  * skipped entirely — only the per-service cache / dirty checks run.
47 |  */
48 | export class ContextGraphEngine {
49 |   private scanner: WorkspaceScanner;
50 |   private apiParser: SpringApiParser;
51 |   private jpaParser: JpaEntityParser;
52 |   private dependencyAnalyzer: DependencyAnalyzer;
53 |   private nodeParser: NodeApiParser;
54 |   private pythonParser: PythonApiParser;
55 |   private goParser: GoApiParser;
56 |   private cache: ContextCache;
57 |   private graphBuilder: ContextGraphBuilder;
58 |   private cacheDir: string;
59 |   private watsonxClient: any = null; // Injected at runtime
60 | 
61 |   constructor(options: AnalysisOptions) {
62 |     this.cacheDir = options.cacheDir ?? path.join(options.workspaceRoot, '.context-graph-cache');
63 |     this.scanner = new WorkspaceScanner(options.workspaceRoot);
64 |     this.apiParser = new SpringApiParser();
65 |     this.jpaParser = new JpaEntityParser();
66 |     this.dependencyAnalyzer = new DependencyAnalyzer();
67 |     this.nodeParser = new NodeApiParser();
68 |     this.pythonParser = new PythonApiParser();
69 |     this.goParser = new GoApiParser();
70 |     this.cache = new ContextCache(this.cacheDir);
71 |     this.graphBuilder = new ContextGraphBuilder();
72 |   }
73 | 
74 |   setWatsonxClient(client: any): void {
75 |     this.watsonxClient = client;
76 |   }
77 | 
78 |   /**
79 |    * Full analysis run: discover services, check cache, analyze as needed.
80 |    *
81 |    * F02: Group discovered services by repository so we only read git diff once per repo.
82 |    * NEW: Uses workspace fingerprint to skip the filesystem crawl when project structure
83 |    *      hasn't changed. Uses dirtyHash compound key so uncommitted edits are detected
84 |    *      without needing a commit.
85 |    */
86 |   async analyze(forceRefresh = false): Promise<AnalysisResult> {
87 |     // ── 1. Service discovery (with workspace-fingerprint shortcut) ──────────
88 |     const discovered = await this.discoverWithFingerprintCache(forceRefresh);
89 |     const stats = { cached: 0, refreshed: 0, failed: 0 };
90 |     const serviceContexts: ServiceContext[] = [];
91 | 
92 |     const serviceIds = discovered.map(d => d.serviceId);
93 | 
94 |     // ── 2. Per-repo HEAD + dirty-hash map ────────────────────────────────────
95 |     // F02: build a per-repository HEAD map so all services in the same repo
96 |     // share the same observed commit and we only call git once per repo.
97 |     const repoHeadMap = new Map<string, string>();
98 |     const repoDirtyMap = new Map<string, string>();
99 |     for (const svc of discovered) {
100 |       if (svc.isGitRepo && !repoHeadMap.has(svc.repository)) {
101 |         const git = new GitAnalyzer(svc.repository);
102 |         repoHeadMap.set(svc.repository, git.getHead(false));
103 |         repoDirtyMap.set(svc.repository, git.getDirtyHash());
104 |       }
105 |     }
106 | 
107 |     for (const svc of discovered) {
108 |       // F02: override commitHash with the authoritative per-repo HEAD
109 |       const repoHead = repoHeadMap.get(svc.repository);
110 |       const repoDirty = repoDirtyMap.get(svc.repository) ?? 'clean';
111 |       const effective: DiscoveredService = repoHead
112 |         ? { ...svc, commitHash: repoHead }
113 |         : svc;
114 | 
115 |       try {
116 |         const ctx = await this.analyzeService(effective, serviceIds, forceRefresh, repoDirty);
117 |         serviceContexts.push(ctx);
118 | 
119 |         if (ctx.status === 'Cached') stats.cached++;
120 |         else stats.refreshed++;
121 |       } catch (err) {
122 |         process.stderr.write(`[BCG] Failed to analyze ${svc.serviceId}: ${err}\n`);
123 |         stats.failed++;
