452 | /**
453 |  * F23: Strict service resolver — reject ambiguous short names.
454 |  * Returns the matched service or throws McpError with candidate list.
455 |  */
456 | function resolveService(serviceArg: string, services: typeof cachedResult extends null ? never : NonNullable<typeof cachedResult>['services']): NonNullable<typeof cachedResult>['services'][number] {
457 |   // 1. Exact canonical ID match
458 |   const exactId = services.find(s => s.identity.serviceId === serviceArg);
459 |   if (exactId) return exactId;
460 | 
461 |   // 2. Exact name match
462 |   const exactName = services.find(s => s.identity.name === serviceArg);
463 |   if (exactName) return exactName;
464 | 
465 |   // 3. Unique prefix/substring match — only if unambiguous
466 |   const partialMatches = services.filter(
467 |     s =>
468 |       s.identity.serviceId.includes(serviceArg) ||
469 |       s.identity.name.includes(serviceArg)
470 |   );
471 | 
472 |   if (partialMatches.length === 1) return partialMatches[0];
473 | 
474 |   if (partialMatches.length > 1) {
475 |     const candidates = partialMatches.map(s => s.identity.serviceId).join(', ');
476 |     throw new McpError(
477 |       ErrorCode.InvalidParams,
478 |       `Ambiguous service name "${serviceArg}". Matching candidates: [${candidates}]. Please use an exact service ID.`
479 |     );
480 |   }
481 | 
482 |   const available = services.map(s => s.identity.serviceId).join(', ');
483 |   throw new McpError(
484 |     ErrorCode.InvalidParams,
485 |     `Service "${serviceArg}" not found. Available: [${available}]`
486 |   );
487 | }
