38 |     const candidates = this.findServiceDirectories(this.workspaceRoot, 0);
39 | 
40 |     for (const candidate of candidates) {
41 |       const service = await this.analyzeDirectory(candidate);
42 |       if (service) {
43 |         services.push(service);
44 |       }
45 |     }
46 | 
47 |     return services;
48 |   }
