50 |   /**
51 |    * Compute a cheap fingerprint of the workspace's service-discovery topology.
52 |    * Hashes the relative paths and sizes of all marker files (pom.xml,
53 |    * package.json, go.mod, etc.) found up to MAX_DEPTH. When this value is
54 |    * the same as what is stored in the cache, service discovery can be skipped
55 |    * entirely and the cached service list reused.
56 |    *
57 |    * No file content is read — only stat() calls, so it is very fast.
58 |    */
59 |   getWorkspaceFingerprint(): string {
60 |     const entries: string[] = [];
61 |     this.collectMarkerFiles(this.workspaceRoot, 0, entries);
62 |     entries.sort();
63 |     return crypto
64 |       .createHash('sha1')
65 |       .update(entries.join('\n'))
66 |       .digest('hex')
67 |       .slice(0, 16);
68 |   }
69 | 
70 |   private collectMarkerFiles(dir: string, depth: number, out: string[]): void {
71 |     if (depth > MAX_DEPTH) return;
72 | 
73 |     let dirEntries: fs.Dirent[];
74 |     try {
75 |       dirEntries = fs.readdirSync(dir, { withFileTypes: true });
76 |     } catch {
77 |       return;
78 |     }
79 | 
80 |     for (const entry of dirEntries) {
81 |       if (entry.isFile() && MARKER_FILES.includes(entry.name)) {
82 |         try {
83 |           const stat = fs.statSync(path.join(dir, entry.name));
84 |           const rel = path.relative(this.workspaceRoot, path.join(dir, entry.name)).replace(/\\/g, '/');
85 |           out.push(`${rel}:${stat.size}`);
86 |         } catch {
87 |           // ignore
88 |         }
89 |       } else if (entry.isDirectory() && !EXCLUDE_DIRS.has(entry.name) && !entry.name.startsWith('.')) {
90 |         this.collectMarkerFiles(path.join(dir, entry.name), depth + 1, out);
91 |       }
92 |     }
93 |   }
94 | 
95 |   private findServiceDirectories(dir: string, depth: number): string[] {
96 |     if (depth > MAX_DEPTH) return [];
97 | 
98 |     const results: string[] = [];
99 | 
100 |     let entries: fs.Dirent[];
101 |     try {
102 |       entries = fs.readdirSync(dir, { withFileTypes: true });
103 |     } catch {
104 |       return results;
105 |     }
106 | 
107 |     // Check if this dir is a service (but not a Maven aggregator)
108 |     const stack = this.detectStack(dir);
109 |     if (stack !== 'unknown' && !this.isMavenAggregator(dir)) {
110 |       results.push(dir);
111 |       // For Spring Boot, do NOT recurse further into this service directory
112 |       if (stack === 'spring-boot') return results;
113 |     }
114 | 
115 |     // If it IS a Maven aggregator, recurse into declared modules
116 |     if (this.isMavenAggregator(dir)) {
117 |       const moduleNames = this.getMavenModules(dir);
118 |       for (const modName of moduleNames) {
119 |         const modPath = path.join(dir, modName);
120 |         if (fs.existsSync(modPath)) {
121 |           const subResults = this.findServiceDirectories(modPath, depth + 1);
122 |           results.push(...subResults);
123 |         }
124 |       }
125 |       return results;
126 |     }
127 | 
128 |     // Recurse into subdirectories
129 |     for (const entry of entries) {
130 |       if (!entry.isDirectory()) continue;
131 |       if (EXCLUDE_DIRS.has(entry.name)) continue;
132 |       if (entry.name.startsWith('.')) continue;
133 | 
134 |       const fullPath = path.join(dir, entry.name);
135 |       const subResults = this.findServiceDirectories(fullPath, depth + 1);
136 |       results.push(...subResults);
137 |     }
138 | 
139 |     return results;
140 |   }
141 | 
142 |   /**
143 |    * Detect the technology stack of a directory.
144 |    */
145 |   detectStack(dir: string): DiscoveredService['detectedStack'] {
146 |     if (fs.existsSync(path.join(dir, 'pom.xml'))) {
147 |       // Could be Spring Boot or Maven aggregator — check content
148 |       const pomContent = this.tryReadFile(path.join(dir, 'pom.xml')) ?? '';
149 |       if (pomContent.includes('spring-boot') || pomContent.includes('springframework')) {
150 |         return 'spring-boot';
151 |       }
152 |       // Has a pom.xml but no Spring — still treat as spring-compatible
153 |       return 'spring-boot';
154 |     }
155 |     if (
156 |       fs.existsSync(path.join(dir, 'build.gradle')) ||
157 |       fs.existsSync(path.join(dir, 'build.gradle.kts'))
158 |     ) {
159 |       return 'spring-boot';
160 |     }
161 |     if (fs.existsSync(path.join(dir, 'package.json'))) {
162 |       return 'node';
163 |     }
164 |     if (
165 |       fs.existsSync(path.join(dir, 'requirements.txt')) ||
166 |       fs.existsSync(path.join(dir, 'pyproject.toml')) ||
167 |       fs.existsSync(path.join(dir, 'setup.py')) ||
168 |       fs.existsSync(path.join(dir, 'setup.cfg'))
169 |     ) {
170 |       return 'python';
171 |     }
172 |     if (fs.existsSync(path.join(dir, 'go.mod'))) {
173 |       return 'go';
174 |     }
175 |     return 'unknown';
176 |   }
177 | 
178 |   /**
179 |    * A Maven aggregator has a pom.xml with <modules> and typically packaging=pom
180 |    * and NO src/main directory (no actual service code).
181 |    */
182 |   private isMavenAggregator(dir: string): boolean {
183 |     const pomPath = path.join(dir, 'pom.xml');
184 |     if (!fs.existsSync(pomPath)) return false;
185 |     const content = this.tryReadFile(pomPath) ?? '';
186 |     if (!content.includes('<modules>')) return false;
187 |     // If it has its own src/main, it's also a service — not a pure aggregator
188 |     if (fs.existsSync(path.join(dir, 'src', 'main'))) return false;
189 |     return true;
190 |   }
191 | 
192 |   /**
193 |    * Extract module names from a Maven aggregator pom.xml.
194 |    */
195 |   private getMavenModules(dir: string): string[] {
196 |     const pomPath = path.join(dir, 'pom.xml');
197 |     const content = this.tryReadFile(pomPath) ?? '';
198 |     const moduleMatches = [...content.matchAll(/<module>\s*([^<]+)\s*<\/module>/g)];
199 |     return moduleMatches.map(m => m[1].trim());
200 |   }
201 | 
202 |   private tryReadFile(filePath: string): string | null {
203 |     try {
204 |       return fs.readFileSync(filePath, 'utf8');
205 |     } catch {
206 |       return null;
207 |     }
208 |   }
209 | 
210 |   private async analyzeDirectory(dirPath: string): Promise<DiscoveredService | null> {
211 |     const stack = this.detectStack(dirPath);
212 |     if (stack === 'unknown') return null;
213 | 
214 |     const name = path.basename(dirPath);
215 | 
216 |     let gitRoot: string | null = null;
217 |     let branch = 'main';
218 |     let commitHash = 'unknown';
219 |     let isGitRepo = false;
220 | 
221 |     try {
222 |       gitRoot = execSync('git rev-parse --show-toplevel', {
223 |         cwd: dirPath,
224 |         encoding: 'utf8',
225 |         stdio: ['pipe', 'pipe', 'pipe'],
226 |       }).trim();
227 | 
228 |       isGitRepo = true;
229 | 
230 |       branch = execSync('git rev-parse --abbrev-ref HEAD', {
231 |         cwd: dirPath,
232 |         encoding: 'utf8',
233 |         stdio: ['pipe', 'pipe', 'pipe'],
234 |       }).trim();
235 | 
236 |       commitHash = execSync('git rev-parse HEAD', {
237 |         cwd: dirPath,
238 |         encoding: 'utf8',
239 |         stdio: ['pipe', 'pipe', 'pipe'],
240 |       }).trim();
241 |     } catch {
242 |       // Not a git repo or git not available
243 |     }
244 | 
245 |     const repository = gitRoot ?? dirPath;
246 | 
247 |     // F09 fix: canonical serviceId = namespace (repo name or workspace-relative path) + service dir name
248 |     const serviceId = this.generateServiceId(dirPath, repository);
249 | 
250 |     return {
251 |       serviceId,
252 |       name,
253 |       rootPath: dirPath,
254 |       repository,
255 |       branch,
256 |       commitHash,
257 |       isGitRepo,
258 |       detectedStack: stack,
259 |     };
260 |   }
261 | 
262 |   /**
263 |    * F09: Generate a canonical, unique service ID.
264 |    * Uses workspace-relative path so two services with the same dir name get different IDs.
265 |    */
266 |   generateServiceId(dirPath: string, repository?: string): string {
267 |     // Make it relative to workspace root to avoid collision
268 |     const relToWorkspace = path.relative(this.workspaceRoot, dirPath);
269 |     // Normalize path separators and sanitize
270 |     const normalized = relToWorkspace
271 |       .replace(/\\/g, '/')
272 |       .toLowerCase()
273 |       .replace(/[^a-z0-9/-]/g, '-')
274 |       .replace(/\/+/g, '-')
275 |       .replace(/^-+|-+$/g, '');
276 |     return normalized || path.basename(dirPath).toLowerCase().replace(/[^a-z0-9-]/g, '-');
277 |   }
278 | 
279 |   countFiles(dirPath: string, extensions: string[] = ['.java']): number {
280 |     let count = 0;
281 |     try {
282 |       const walk = (dir: string) => {
283 |         const entries = fs.readdirSync(dir, { withFileTypes: true });
284 |         for (const entry of entries) {
285 |           if (EXCLUDE_DIRS.has(entry.name)) continue;
286 |           const full = path.join(dir, entry.name);
287 |           if (entry.isDirectory()) {
288 |             walk(full);
289 |           } else if (extensions.some(ext => entry.name.endsWith(ext))) {
290 |             count++;
291 |           }
292 |         }
293 |       };
294 |       walk(dirPath);
295 |     } catch {
296 |       // ignore
297 |     }
298 |     return count;
299 |   }
300 | }
