10 | /**
11 |  * Builds and maintains the System Context Graph from ServiceContexts.
12 |  */
13 | export class ContextGraphBuilder {
14 |   /**
15 |    * Build a complete system graph from all service contexts.
16 |    * F17: merge tables from multiple services that share the same database name.
17 |    */
18 |   build(services: ServiceContext[]): SystemContextGraph {
19 |     const nodes: GraphNode[] = [];
20 |     const edges: GraphEdge[] = [];
21 | 
22 |     // F17: Accumulate tables per DB node — multiple services may share a DB
23 |     const dbNodeDataMap = new Map<string, { tables: DatabaseTable[]; ownerServiceIds: string[] }>();
24 | 
25 |     // Create service nodes
26 |     for (const svc of services) {
27 |       nodes.push({
28 |         id: svc.identity.serviceId,
29 |         type: 'SERVICE',
30 |         label: svc.identity.name,
31 |         data: svc,
32 |       });
33 | 
34 |       // Create database nodes for each table group
35 |       const dbNames = this.inferDatabaseNames(svc);
36 |       for (const dbName of dbNames) {
37 |         // Merge tables when multiple services share the same DB
38 |         const existing = dbNodeDataMap.get(dbName);
39 |         if (existing) {
40 |           // Add tables not already present (by tableName)
41 |           for (const table of svc.database) {
42 |             if (!existing.tables.find(t => t.tableName === table.tableName)) {
43 |               existing.tables.push(table);
44 |             }
45 |           }
46 |           if (!existing.ownerServiceIds.includes(svc.identity.serviceId)) {
47 |             existing.ownerServiceIds.push(svc.identity.serviceId);
48 |           }
49 |         } else {
50 |           dbNodeDataMap.set(dbName, {
51 |             tables: [...svc.database],
52 |             ownerServiceIds: [svc.identity.serviceId],
53 |           });
54 |         }
55 | 
56 |         // Add Service → Database edge (deduplicated)
57 |         const edgeId = `${svc.identity.serviceId}->db:${dbName}`;
58 |         if (!edges.find(e => e.id === edgeId)) {
59 |           edges.push({
60 |             id: edgeId,
61 |             type: 'SERVICE_USES_DATABASE',
62 |             source: svc.identity.serviceId,
63 |             target: `db:${dbName}`,
64 |             label: 'uses',
65 |           });
66 |         }
67 |       }
68 |     }
69 | 
70 |     // Add database nodes to main nodes array
71 |     for (const [dbName, dbData] of dbNodeDataMap) {
72 |       const dbNodeData: DatabaseNodeData = {
73 |         name: dbName,
74 |         tables: dbData.tables,
75 |         ownerServiceId: dbData.ownerServiceIds[0],
76 |         ownerServiceIds: dbData.ownerServiceIds,
77 |       };
78 |       nodes.push({
79 |         id: `db:${dbName}`,
80 |         type: 'DATABASE',
81 |         label: dbName,
82 |         data: dbNodeData,
83 |       });
84 |     }
85 | 
86 |     // Create service → service dependency edges
87 |     for (const svc of services) {
88 |       for (const dep of svc.dependencies) {
89 |         // Find target service node
90 |         const targetId = this.resolveServiceId(dep.targetService, services);
91 |         if (targetId) {
92 |           const edgeId = `${svc.identity.serviceId}->${targetId}`;
93 |           // Avoid duplicate edges
94 |           if (!edges.find(e => e.id === edgeId)) {
95 |             edges.push({
96 |               id: edgeId,
97 |               type: 'SERVICE_DEPENDS_ON_SERVICE',
98 |               source: svc.identity.serviceId,
99 |               target: targetId,
100 |               label: 'depends on',
101 |             });
102 |           }
103 |         }
104 |       }
105 |     }
106 | 
107 |     return {
108 |       nodes,
109 |       edges,
110 |       generatedAt: new Date().toISOString(),
111 |     };
112 |   }
113 | 
114 |   /**
115 |    * Apply impact highlighting to graph nodes.
116 |    * F17: Match using nodeId (e.g. db:orders_db) if present, else fall back to label matching.
117 |    */
118 |   applyImpact(
119 |     graph: SystemContextGraph,
120 |     impacts: Array<{ component: string; severity: 'HIGH' | 'MEDIUM' | 'LOW'; reason: string; nodeId?: string }>
121 |   ): SystemContextGraph {
122 |     const updatedNodes = graph.nodes.map(node => {
123 |       // F17: prefer explicit nodeId match over label substring matching
124 |       const impact = impacts.find(i => {
125 |         if (i.nodeId) return i.nodeId === node.id;
126 |         const comp = i.component.toLowerCase();
127 |         const nodeLabel = node.label.toLowerCase();
128 |         const nodeId = node.id.toLowerCase();
129 |         // Exact label or ID match
130 |         if (comp === nodeLabel || comp === nodeId) return true;
131 |         // For DB nodes: "order-service Database" → check if node label is a substring of the service name
132 |         if (node.type === 'DATABASE' && comp.includes('database')) {
133 |           // Extract service base name from component: "order-service Database" → "order"
134 |           const servicePart = comp.replace(/\s*database\s*/g, '').replace(/-service$/, '').trim();
135 |           // Check if the DB label contains the service name prefix
136 |           const dbBase = nodeLabel.replace(/_db$/, '').replace(/_v\d+$/, '');
137 |           return dbBase.startsWith(servicePart) || servicePart.startsWith(dbBase);
138 |         }
139 |         // Substring fallback for non-DB nodes
140 |         if (node.type !== 'DATABASE') {
141 |           return comp.includes(nodeLabel) || nodeLabel.includes(comp);
142 |         }
143 |         return false;
144 |       });
145 | 
146 |       if (impact) {
147 |         return { ...node, impactSeverity: impact.severity, impactReason: impact.reason };
148 |       }
149 | 
150 |       return { ...node, impactSeverity: 'SAFE' as const };
151 |     });
152 | 
153 |     return { ...graph, nodes: updatedNodes };
154 |   }
155 | 
156 |   /**
157 |    * Serialize graph to JSON-compatible format for VSIX webview.
158 |    */
159 |   toVisualizationFormat(graph: SystemContextGraph): object {
160 |     return {
161 |       nodes: graph.nodes.map(n => ({
162 |         id: n.id,
163 |         type: n.type,
164 |         label: n.label,
165 |         status: this.getNodeStatus(n),
166 |         impactSeverity: n.impactSeverity,
167 |         impactReason: n.impactReason,
168 |         data: this.summarizeNodeData(n),
169 |       })),
170 |       edges: graph.edges.map(e => ({
171 |         id: e.id,
172 |         source: e.source,
173 |         target: e.target,
174 |         type: e.type,
175 |         label: e.label,
176 |       })),
177 |       generatedAt: graph.generatedAt,
178 |     };
179 |   }
180 | 
181 |   private inferDatabaseNames(svc: ServiceContext): string[] {
182 |     const names: string[] = [];
183 | 
184 |     // From dependencies marked as DATABASE
185 |     const dbDeps = svc.dependencies.filter(d => d.type === 'DATABASE');
186 |     names.push(...dbDeps.map(d => d.targetService));
187 | 
188 |     // Infer from service name if has entities
189 |     if (svc.database.length > 0 && names.length === 0) {
190 |       names.push(svc.identity.name.replace('-service', '') + '_db');
191 |     }
192 | 
193 |     return [...new Set(names)];
194 |   }
195 | 
196 |   private resolveServiceId(targetService: string, services: ServiceContext[]): string | null {
197 |     // Direct match
198 |     const direct = services.find(s => s.identity.serviceId === targetService);
199 |     if (direct) return direct.identity.serviceId;
200 | 
201 |     // Partial match
202 |     const partial = services.find(
203 |       s =>
204 |         s.identity.serviceId.includes(targetService) ||
205 |         targetService.includes(s.identity.serviceId) ||
206 |         s.identity.name.toLowerCase().includes(targetService.toLowerCase()) ||
207 |         targetService.toLowerCase().includes(s.identity.name.toLowerCase())
208 |     );
209 |     if (partial) return partial.identity.serviceId;
210 | 
211 |     return null;
212 |   }
213 | 
214 |   private getNodeStatus(node: GraphNode): string {
215 |     if (node.type === 'DATABASE') return 'database';
216 |     const svc = node.data as ServiceContext;
217 |     return svc.status || 'Unknown';
218 |   }
219 | 
220 |   private summarizeNodeData(node: GraphNode): object {
221 |     if (node.type === 'DATABASE') {
222 |       const db = node.data as DatabaseNodeData;
223 |       return {
224 |         name: db.name,
225 |         tableCount: db.tables.length,
226 |         owner: db.ownerServiceId,
227 |       };
228 |     }
229 | 
230 |     const svc = node.data as ServiceContext;
231 |     return {
232 |       serviceId: svc.identity.serviceId,
233 |       commit: svc.identity.commitHash,
234 |       branch: svc.identity.branch,
235 |       apiCount: svc.apis.length,
236 |       tableCount: svc.database.length,
237 |       dependencyCount: svc.dependencies.length,
238 |       status: svc.status,
239 |       analyzedAt: svc.analyzedAt,
240 |       semanticSummary: svc.semanticSummary,
241 |     };
242 |   }
243 | }
