5 | /**
6 |  * Parses Spring Boot Java source files to extract REST API endpoints.
7 |  * Uses regex-based parsing with multiline annotation support.
8 |  *
9 |  * F15 fixes:
10 |  * - Handle path= alias in @RequestMapping (not just value=)
11 |  * - Handle @RequestBody on a following line (multiline signatures)
12 |  * - Correctly parse nested generics like ResponseEntity<List<OrderResponse>>
13 |  * - Handle array-style @RequestMapping(value={"/v1"})
14 |  */
15 | export class SpringApiParser {
16 |   /**
17 |    * Parse all Java files in a service directory and extract endpoints.
18 |    */
19 |   parseService(serviceRoot: string): ApiEndpoint[] {
20 |     const endpoints: ApiEndpoint[] = [];
21 |     const javaFiles = this.findJavaFiles(serviceRoot);
22 | 
23 |     for (const file of javaFiles) {
24 |       try {
25 |         const content = fs.readFileSync(file, 'utf8');
26 |         if (this.isRestController(content)) {
27 |           const fileEndpoints = this.parseController(file, content);
28 |           endpoints.push(...fileEndpoints);
29 |         }
30 |       } catch {
31 |         // skip unreadable files
32 |       }
33 |     }
34 | 
35 |     return endpoints;
36 |   }
37 | 
38 |   private isRestController(content: string): boolean {
39 |     return /@RestController/.test(content) || /@Controller/.test(content);
40 |   }
41 | 
42 |   private parseController(filePath: string, content: string): ApiEndpoint[] {
43 |     const endpoints: ApiEndpoint[] = [];
44 |     const controllerName = path.basename(filePath, '.java');
45 | 
46 |     // Extract class-level @RequestMapping prefix
47 |     const classMapping = this.extractClassMapping(content);
48 | 
49 |     // Extract all handler methods
50 |     const lines = content.split('\n');
51 |     const methods = this.extractHandlerMethods(lines, classMapping, controllerName);
52 |     endpoints.push(...methods);
53 | 
54 |     return endpoints;
55 |   }
56 | 
57 |   /**
58 |    * F15: Extract class-level @RequestMapping, supporting both value= and path= aliases.
59 |    * Also handles array syntax: @RequestMapping({"/v1"}) or @RequestMapping(path={"/v1", "/api/v1"})
60 |    */
61 |   private extractClassMapping(content: string): string {
62 |     // Collect the full @RequestMapping annotation block (may span multiple lines)
63 |     const annotMatch = content.match(/@RequestMapping\s*(\([^)]*\))/s);
64 |     if (!annotMatch) return '';
65 | 
66 |     const body = annotMatch[1];
67 |     // Try value= or path= with quoted string
68 |     const aliasMatch = body.match(/(?:value|path)\s*=\s*(?:\{[^}]*\}|["']([^"']+)["'])/);
69 |     if (aliasMatch) {
70 |       if (aliasMatch[1]) return aliasMatch[1];
71 |       // Array form: pick the first entry
72 |       const arrMatch = body.match(/["']([^"']+)["']/);
73 |       if (arrMatch) return arrMatch[1];
74 |     }
75 |     // Bare value: @RequestMapping("/api")
76 |     const bareMatch = body.match(/["']([^"']+)["']/);
77 |     if (bareMatch) return bareMatch[1];
78 | 
79 |     return '';
80 |   }

