5 | /**
6 |  * Detects dependencies between Spring Boot services by analyzing:
7 |  * - RestTemplate / WebClient / FeignClient calls
8 |  * - Service references in application.properties/yml
9 |  * - Import patterns
10 |  */
11 | export class DependencyAnalyzer {
12 |   /**
13 |    * Detect service dependencies from source code.
14 |    * @param serviceRoot - Root directory of the service being analyzed
15 |    * @param knownServices - IDs of other known services in the workspace
16 |    */
17 |   analyzeDependencies(serviceRoot: string, knownServices: string[]): ServiceDependency[] {
18 |     const dependencies: ServiceDependency[] = [];
19 |     const javaFiles = this.findJavaFiles(serviceRoot);
20 | 
21 |     const restDeps = this.findRestClientDependencies(javaFiles, knownServices, serviceRoot);
22 |     const configDeps = this.findConfigDependencies(serviceRoot, knownServices);
23 | 
24 |     // Merge, deduplicating by target service
25 |     const merged = new Map<string, ServiceDependency>();
26 | 
27 |     for (const dep of [...restDeps, ...configDeps]) {
28 |       const existing = merged.get(dep.targetService);
29 |       if (existing) {
30 |         if (dep.endpoints) {
31 |           existing.endpoints = [...(existing.endpoints || []), ...dep.endpoints];
32 |         }
33 |         existing.evidence += '; ' + dep.evidence;
34 |       } else {
35 |         merged.set(dep.targetService, { ...dep });
36 |       }
37 |     }
38 | 
39 |     return Array.from(merged.values());
40 |   }
41 | 
42 |   private findRestClientDependencies(
43 |     javaFiles: string[],
44 |     knownServices: string[],
45 |     serviceRoot: string
46 |   ): ServiceDependency[] {
47 |     const deps: ServiceDependency[] = [];
48 | 
49 |     for (const file of javaFiles) {
50 |       try {
51 |         const content = fs.readFileSync(file, 'utf8');
52 | 
53 |         // Look for @FeignClient(name = "inventory-service")
54 |         const feignMatches = [...content.matchAll(/@FeignClient\s*\(\s*(?:name\s*=\s*)?["']([^"']+)["']/g)];
55 |         for (const m of feignMatches) {
56 |           deps.push({
57 |             targetService: m[1],
58 |             type: 'REST',
59 |             evidence: `FeignClient in ${path.basename(file)}`,
60 |           });
61 |         }
62 | 
63 |         // Look for URL patterns like "http://inventory-service/" or "${inventory-service.url}"
64 |         const urlMatches = [...content.matchAll(/["']https?:\/\/([a-z0-9-]+)[/:]["']/g)];
65 |         for (const m of urlMatches) {
66 |           const svcName = m[1];
67 |           if (knownServices.some(s => s.includes(svcName) || svcName.includes(s.replace('-service', '')))) {
68 |             deps.push({
69 |               targetService: svcName,
70 |               type: 'REST',
71 |               evidence: `HTTP call to ${svcName} in ${path.basename(file)}`,
72 |             });
73 |           }
74 |         }
75 | 
76 |         // Look for RestTemplate or WebClient usage with service names
77 |         if (/RestTemplate|WebClient/.test(content)) {
78 |           for (const svc of knownServices) {
79 |             const svcBase = svc.replace('-service', '');
80 |             const regex = new RegExp(`["'\`](?:[^"'\`]*${svcBase}[^"'\`]*)["'\`]`, 'gi');
81 |             if (regex.test(content)) {
82 |               deps.push({
83 |                 targetService: svc,
84 |                 type: 'REST',
85 |                 evidence: `RestTemplate/WebClient reference to ${svc} in ${path.basename(file)}`,
86 |               });
87 |             }
88 |           }
89 |         }
90 |       } catch {
91 |         // skip
92 |       }
93 |     }
94 | 
95 |     return deps;
96 |   }
