  function getServiceStroke(node) {
    if (node.impactSeverity === 'HIGH') return '#ef5350';
    if (node.impactSeverity === 'MEDIUM') return '#ffa726';
    if (node.impactSeverity === 'SAFE') return '#66bb6a';
