      status: s.status,
      apiCount: s.apis.length,
      tableCount: s.database.length,
      dependencyCount: s.dependencies.length,
      dependencies: s.dependencies.map(d => ({ target: d.targetService, type: d.type })),
      semanticSummary: s.semanticSummary,
