  set(context: ServiceContext, dirtyHash = 'clean'): void {
    const { serviceId, branch, commitHash } = context.identity;

    // Write context file
    const filePath = this.contextFilePath(serviceId, branch, commitHash, dirtyHash);
    try {
      const tmp = filePath + '.tmp';
