  private async discoverWithFingerprintCache(forceRefresh: boolean): Promise<DiscoveredService[]> {
    const currentFingerprint = this.scanner.getWorkspaceFingerprint();

    if (!forceRefresh) {
      const stored = this.cache.getWorkspaceFingerprint();
