      baselineCommit: prevCommit !== commitHash ? prevCommit : (existing?.baselineCommit ?? null),
      previousCommit: prevCommit,
      lastAnalyzedAt: new Date().toISOString(),
      schemaVersion: SCHEMA_VERSION,
    };
    this.saveIndex();
  }

