   * we write it back as the baseline; otherwise the current baseline advance rule applies.
   */
  restoreBaseline(serviceId: string, savedBaseline: string | null, savedLastCommit: string | null): void {
    const existing = this.index.metadata[serviceId];
    if (!existing) return;

