    this.index = this.loadIndex();
  }

  private loadIndex(): CacheIndex {
    try {
      if (fs.existsSync(this.indexPath)) {
        const parsed = JSON.parse(fs.readFileSync(this.indexPath, 'utf8')) as CacheIndex;
        // Validate and migrate per-entry schema versions
        const migratedMetadata: Record<string, CacheMetadata> = {};
        for (const [serviceId, meta] of Object.entries(parsed.metadata)) {
          const m = meta as any;
          const version = typeof m.schemaVersion === 'number' ? m.schemaVersion : 0;

          // Schema version 0 = explicitly invalidated or corrupt — drop the entry
          if (version === 0) {
            process.stderr.write(`[BCG] Cache: dropping invalid schema entry for ${serviceId} (schemaVersion=0)\n`);
            continue;
          }

          // Version 1 = pre-baseline tracking: migrate by adding missing fields
          if (version < 2) {
            process.stderr.write(`[BCG] Cache: migrating schema entry for ${serviceId} (v${version} → 2)\n`);
            m.schemaVersion = 2;
            m.baselineCommit = m.previousCommit ?? null;
          }
          if (!('lastDirtyHash' in m)) {
