    try {
      // Atomic write: write to temp then rename
      const tmp = this.indexPath + '.tmp';
      fs.writeFileSync(tmp, JSON.stringify(this.index, null, 2), 'utf8');
      fs.renameSync(tmp, this.indexPath);
    } catch {
      // ignore write errors
    }
