    const entries: string[] = [];
    this.collectMarkerFiles(this.workspaceRoot, 0, entries);
    entries.sort();
    return crypto
      .createHash('sha1')
      .update(entries.join('\n'))
      .digest('hex')
      .slice(0, 16);
