          const stat = fs.statSync(path.join(dir, entry.name));
          const rel = path.relative(this.workspaceRoot, path.join(dir, entry.name)).replace(/\\/g, '/');
          out.push(`${rel}:${stat.size}`);
        } catch {
          // ignore
