    const m = methodLine.match(/@RequestBody\s+(\w+)/);
    return m ? m[1] : undefined;
  }

  private cleanGenericType(type: string): string {
    return type.replace(/\s/g, '').trim();
  }

  private joinPaths(...parts: string[]): string {
    const joined = parts
      .filter(p => p)
      .join('/')
      .replace(/\/+/g, '/');
