+Service: ${context.identity.name}
+APIs: ${apis || 'none'}
+Database tables: ${tables || 'none'}
+Dependencies: ${deps || 'none'}
+
+Summary:`;
+  }
+
+  private buildImpactPrompt(
+    changeDescription: string,
+    changedService: ServiceContext,
