215 |       affectsDatabase: changedFiles.some(f => f.category === 'ENTITY'),
216 |       affectsDependencies: changedFiles.some(f => ['SERVICE', 'CONFIG'].includes(f.category)),
217 |     };
218 | 
219 |     // Get previous context as baseline
220 |     const previousContext = this.cache.get(serviceId, branch, oldCommit);
221 | 
222 |     if (!previousContext) {
223 |       // No baseline - do full analysis
224 |       return this.fullAnalysis(discovered, allServiceIds);
225 |     }
226 | 
227 |     // Build updated context
228 |     const updated: ServiceContext = { ...previousContext };
229 |     updated.identity = { ...previousContext.identity, commitHash, previousCommitHash: oldCommit };
230 |     updated.analyzedAt = new Date().toISOString();
231 |     updated.status = 'Changed';
232 | 
233 |     // Re-analyze only affected sections
234 |     if (changeSet.affectsApi) {
235 |       console.log(`[BCG] Re-analyzing APIs for ${serviceId}`);
236 |       updated.apis = this.apiParser.parseService(rootPath);
237 |     }
238 | 
239 |     if (changeSet.affectsDatabase) {
