246 |       const otherServices = allServiceIds.filter(id => id !== serviceId);
247 |       updated.dependencies = this.dependencyAnalyzer.analyzeDependencies(rootPath, otherServices);
248 |     }
249 | 
250 |     // Regenerate semantic summary
251 |     if (this.watsonxClient && (changeSet.affectsApi || changeSet.affectsDatabase)) {
252 |       try {
253 |         updated.semanticSummary = await this.watsonxClient.generateServiceSummary(updated);
254 |       } catch {
255 |         // keep old summary
256 |       }
257 |     }
258 | 
259 |     this.cache.set(updated);
