17 |   async discoverServices(): Promise<DiscoveredService[]> {
18 |     const services: DiscoveredService[] = [];
19 |     const candidates = this.findServiceDirectories(this.workspaceRoot);
20 | 
21 |     for (const candidate of candidates) {
22 |       const service = await this.analyzeDirectory(candidate);
23 |       if (service) {
24 |         services.push(service);
25 |       }
26 |     }
27 | 
