31 |   private findServiceDirectories(root: string): string[] {
32 |     const results: string[] = [];
33 | 
34 |     // Check root itself
35 |     if (this.isServiceDirectory(root)) {
36 |       results.push(root);
37 |       return results; // Don't recurse into a service dir
38 |     }
39 | 
40 |     try {
41 |       const entries = fs.readdirSync(root, { withFileTypes: true });
42 |       for (const entry of entries) {
43 |         if (!entry.isDirectory()) continue;
44 |         if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
45 | 
46 |         const fullPath = path.join(root, entry.name);
47 |         if (this.isServiceDirectory(fullPath)) {
48 |           results.push(fullPath);
49 |         } else {
50 |           // Check one level deeper (monorepo style)
51 |           try {
52 |             const sub = fs.readdirSync(fullPath, { withFileTypes: true });
53 |             for (const subEntry of sub) {
54 |               if (!subEntry.isDirectory()) continue;
55 |               if (subEntry.name.startsWith('.')) continue;
56 |               const subPath = path.join(fullPath, subEntry.name);
57 |               if (this.isServiceDirectory(subPath)) {
58 |                 results.push(subPath);
59 |               }
60 |             }
61 |           } catch {
62 |             // ignore unreadable
63 |           }
64 |         }
65 |       }
66 |     } catch {
67 |       // ignore
68 |     }
69 | 
70 |     return results;
71 |   }
