83 |     const lower = filePath.toLowerCase();
84 |     const basename = path.basename(lower);
85 | 
86 |     if (basename.endsWith('controller.java')) return 'API';
87 |     if (lower.includes('/controller/')) return 'API';
88 |     if (basename.endsWith('entity.java')) return 'ENTITY';
89 |     if (lower.includes('/entity/') || lower.includes('/entities/')) return 'ENTITY';
90 |     if (lower.includes('/model/') || basename.endsWith('dto.java') || basename.endsWith('request.java') || basename.endsWith('response.java')) return 'DTO';
91 |     if (lower.includes('/service/') && basename.endsWith('service.java')) return 'SERVICE';
92 |     if (lower.includes('application.properties') || lower.includes('application.yml') || basename === 'pom.xml') return 'CONFIG';
