25 |         type: 'SERVICE',
26 |         label: svc.identity.name,
27 |         data: svc,
28 |       });
29 | 
30 |       // Create database nodes for each table group
31 |       const dbNames = this.inferDatabaseNames(svc);
32 |       for (const dbName of dbNames) {
33 |         if (!dbNodes.has(dbName)) {
34 |           const dbNodeData: DatabaseNodeData = {
35 |             name: dbName,
36 |             tables: svc.database,
37 |             ownerServiceId: svc.identity.serviceId,
38 |           };
39 |           const dbNode: GraphNode = {
40 |             id: `db:${dbName}`,
41 |             type: 'DATABASE',
42 |             label: dbName,
43 |             data: dbNodeData,
44 |           };
45 |           dbNodes.set(dbName, dbNode);
46 |         }
47 | 
48 |         // Add Service → Database edge
49 |         edges.push({
50 |           id: `${svc.identity.serviceId}->db:${dbName}`,
51 |           type: 'SERVICE_USES_DATABASE',
52 |           source: svc.identity.serviceId,
53 |           target: `db:${dbName}`,
54 |           label: 'uses',
55 |         });
56 |       }
57 |     }
58 | 
59 |     // Add database nodes to main nodes array
60 |     nodes.push(...dbNodes.values());
61 | 
62 |     // Create service → service dependency edges
63 |     for (const svc of services) {
64 |       for (const dep of svc.dependencies) {
65 |         // Find target service node
66 |         const targetId = this.resolveServiceId(dep.targetService, services);
67 |         if (targetId) {
68 |           const edgeId = `${svc.identity.serviceId}->${targetId}`;
69 |           // Avoid duplicate edges
70 |           if (!edges.find(e => e.id === edgeId)) {
71 |             edges.push({
72 |               id: edgeId,
73 |               type: 'SERVICE_DEPENDS_ON_SERVICE',
74 |               source: svc.identity.serviceId,
75 |               target: targetId,
76 |               label: 'depends on',
77 |             });
78 |           }
79 |         }
80 |       }
81 |     }
