140 |   private inferDatabaseNames(svc: ServiceContext): string[] {
141 |     const names: string[] = [];
142 | 
143 |     // From dependencies marked as DATABASE
144 |     const dbDeps = svc.dependencies.filter(d => d.type === 'DATABASE');
145 |     names.push(...dbDeps.map(d => d.targetService));
146 | 
147 |     // Infer from service name if has entities
148 |     if (svc.database.length > 0 && names.length === 0) {
149 |       names.push(svc.identity.name.replace('-service', '') + '_db');
150 |     }
