158 |     if (direct) return direct.identity.serviceId;
159 | 
160 |     // Partial match
161 |     const partial = services.find(
162 |       s =>
163 |         s.identity.serviceId.includes(targetService) ||
164 |         targetService.includes(s.identity.serviceId) ||
165 |         s.identity.name.toLowerCase().includes(targetService.toLowerCase()) ||
166 |         targetService.toLowerCase().includes(s.identity.name.toLowerCase())
