5 | /**
6 |  * Parses Spring Boot Java source files to extract REST API endpoints.
7 |  * Uses regex-based parsing (no full Java AST required for hackathon).
8 |  */
9 | export class SpringApiParser {
10 |   /**
11 |    * Parse all Java files in a service directory and extract endpoints.
12 |    */
13 |   parseService(serviceRoot: string): ApiEndpoint[] {
14 |     const endpoints: ApiEndpoint[] = [];
15 |     const javaFiles = this.findJavaFiles(serviceRoot);
16 | 
17 |     for (const file of javaFiles) {
18 |       try {
19 |         const content = fs.readFileSync(file, 'utf8');
20 |         if (this.isRestController(content)) {
21 |           const fileEndpoints = this.parseController(file, content);
22 |           endpoints.push(...fileEndpoints);
23 |         }
24 |       } catch {
25 |         // skip unreadable files
26 |       }
27 |     }
28 | 
29 |     return endpoints;
30 |   }
31 | 
32 |   private isRestController(content: string): boolean {
33 |     return /@RestController/.test(content) || /@Controller/.test(content);
34 |   }
35 | 
36 |   private parseController(filePath: string, content: string): ApiEndpoint[] {
37 |     const endpoints: ApiEndpoint[] = [];
38 |     const controllerName = path.basename(filePath, '.java');
39 | 
40 |     // Extract class-level @RequestMapping
41 |     const classMapping = this.extractClassMapping(content);
42 | 
43 |     // Extract all handler methods
44 |     const lines = content.split('\n');
45 |     const methods = this.extractHandlerMethods(lines, classMapping, controllerName);
46 |     endpoints.push(...methods);
47 | 
48 |     return endpoints;
49 |   }
50 | 
51 |   private extractClassMapping(content: string): string {
52 |     const match = content.match(/@RequestMapping\s*\(\s*(?:value\s*=\s*)?["']([^"']+)["']/);
53 |     return match ? match[1] : '';
54 |   }
55 | 
56 |   private extractHandlerMethods(
57 |     lines: string[],
58 |     classPath: string,
59 |     controllerName: string
60 |   ): ApiEndpoint[] {
61 |     const endpoints: ApiEndpoint[] = [];
62 |     const httpMethodAnnotations = [
63 |       { pattern: /@GetMapping/, method: 'GET' as const },
64 |       { pattern: /@PostMapping/, method: 'POST' as const },
65 |       { pattern: /@PutMapping/, method: 'PUT' as const },
66 |       { pattern: /@DeleteMapping/, method: 'DELETE' as const },
67 |       { pattern: /@PatchMapping/, method: 'PATCH' as const },
68 |     ];
69 | 
70 |     for (let i = 0; i < lines.length; i++) {
71 |       const line = lines[i].trim();
72 | 
73 |       for (const { pattern, method } of httpMethodAnnotations) {
74 |         if (!pattern.test(line)) continue;
75 | 
76 |         // Extract path from annotation
77 |         const annotationPath = this.extractAnnotationPath(line, lines, i);
78 |         const fullPath = this.joinPaths(classPath, annotationPath);
79 | 
80 |         // Look ahead for method signature
81 |         const methodInfo = this.extractMethodSignature(lines, i);
82 | 
83 |         endpoints.push({
84 |           method,
85 |           path: fullPath || '/',
86 |           controller: controllerName,
87 |           handlerMethod: methodInfo.name,
88 |           requestModel: methodInfo.requestModel,
89 |           responseModel: methodInfo.responseModel,
90 |         });
91 |         break;
92 |       }
93 | 
94 |       // Also handle @RequestMapping on methods
95 |       if (/@RequestMapping\s*\(/.test(line)) {
96 |         const httpMethod = this.extractRequestMappingMethod(line);
97 |         if (httpMethod) {
98 |           const annotationPath = this.extractAnnotationPath(line, lines, i);
99 |           const fullPath = this.joinPaths(classPath, annotationPath);
100 |           const methodInfo = this.extractMethodSignature(lines, i);
101 | 
102 |           endpoints.push({
103 |             method: httpMethod,
104 |             path: fullPath || '/',
105 |             controller: controllerName,
106 |             handlerMethod: methodInfo.name,
107 |             requestModel: methodInfo.requestModel,
108 |             responseModel: methodInfo.responseModel,
109 |           });
110 |         }
111 |       }
112 |     }
113 | 
114 |     return endpoints;
115 |   }
116 | 
117 |   private extractAnnotationPath(line: string, lines: string[], index: number): string {
118 |     // Check current line for path in annotation
119 |     let annotationText = line;
120 | 
121 |     // If annotation spans multiple lines, collect them
122 |     if (line.includes('(') && !line.includes(')')) {
123 |       for (let j = index + 1; j < Math.min(index + 5, lines.length); j++) {
124 |         annotationText += ' ' + lines[j].trim();
125 |         if (lines[j].includes(')')) break;
126 |       }
127 |     }
128 | 
129 |     // Try to extract path value
130 |     const patterns = [
131 |       /(?:value\s*=\s*)?["']([^"']+)["']/,
132 |       /\{\s*["']([^"']+)["']/,
133 |     ];
134 | 
135 |     for (const p of patterns) {
136 |       const m = annotationText.match(p);
137 |       if (m) return m[1];
138 |     }
139 | 
140 |     return '';
141 |   }
142 | 
143 |   private extractRequestMappingMethod(line: string): ApiEndpoint['method'] | null {
144 |     const m = line.match(/method\s*=\s*RequestMethod\.(\w+)/);
145 |     if (!m) return null;
146 |     const method = m[1].toUpperCase();
147 |     if (['GET', 'POST', 'PUT', 'DELETE', 'PATCH'].includes(method)) {
148 |       return method as ApiEndpoint['method'];
149 |     }
150 |     return null;
151 |   }
152 | 
153 |   private extractMethodSignature(
154 |     lines: string[],
155 |     annotationIndex: number
156 |   ): { name: string; requestModel?: string; responseModel?: string } {
157 |     // Look at lines after the annotation for the method signature
158 |     for (let i = annotationIndex + 1; i < Math.min(annotationIndex + 10, lines.length); i++) {
159 |       const line = lines[i].trim();
160 | 
161 |       // Skip other annotations
162 |       if (line.startsWith('@')) continue;
163 |       if (line.length === 0) continue;
164 | 
165 |       // Try to parse method signature
166 |       // e.g.: public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest request)
167 |       const methodMatch = line.match(
168 |         /(?:public|protected|private)?\s+(?:[\w<>\[\],\s]+)\s+(\w+)\s*\(/
169 |       );
170 |       if (methodMatch) {
171 |         const name = methodMatch[1];
172 |         const responseModel = this.extractResponseType(line);
173 |         const requestModel = this.extractRequestBodyType(line);
174 |         return { name, requestModel, responseModel };
175 |       }
176 |     }
177 | 
178 |     return { name: 'unknown' };
179 |   }
180 | 
181 |   private extractResponseType(methodLine: string): string | undefined {
182 |     // ResponseEntity<Foo> or List<Foo> or Foo
183 |     const m = methodLine.match(/ResponseEntity\s*<([^>]+)>/);
184 |     if (m) return this.cleanGenericType(m[1]);
185 | 
186 |     const m2 = methodLine.match(/(?:public|protected|private)\s+([\w<>\[\]]+)\s+\w+\s*\(/);
187 |     if (m2 && !['void', 'String', 'boolean', 'int', 'long'].includes(m2[1])) {
188 |       return this.cleanGenericType(m2[1]);
189 |     }
190 | 
191 |     return undefined;
192 |   }
193 | 
194 |   private extractRequestBodyType(methodLine: string): string | undefined {
195 |     const m = methodLine.match(/@RequestBody\s+(\w+)/);
196 |     return m ? m[1] : undefined;
197 |   }
198 | 
199 |   private cleanGenericType(type: string): string {
200 |     return type.replace(/\s/g, '').trim();
201 |   }
202 | 
203 |   private joinPaths(...parts: string[]): string {
204 |     const joined = parts
205 |       .filter(p => p)
206 |       .join('/')
207 |       .replace(/\/+/g, '/');
208 |     return joined.startsWith('/') ? joined : '/' + joined;
209 |   }
210 | 
211 |   private findJavaFiles(dir: string): string[] {
212 |     const results: string[] = [];
213 |     try {
214 |       const walk = (current: string) => {
215 |         const entries = fs.readdirSync(current, { withFileTypes: true });
216 |         for (const entry of entries) {
217 |           if (entry.name === 'target' || entry.name === '.git' || entry.name === 'node_modules') continue;
218 |           const full = path.join(current, entry.name);
219 |           if (entry.isDirectory()) {
220 |             walk(full);
221 |           } else if (entry.name.endsWith('.java')) {
222 |             results.push(full);
223 |           }
224 |         }
225 |       };
226 |       walk(dir);
227 |     } catch {
228 |       // ignore
229 |     }
230 |     return results;
231 |   }
232 | }
