5 | /**
6 |  * Parses Spring/JPA entity classes to extract database schema information.
7 |  */
8 | export class JpaEntityParser {
9 |   /**
10 |    * Parse all JPA entities in a service directory.
11 |    */
12 |   parseService(serviceRoot: string): DatabaseTable[] {
13 |     const tables: DatabaseTable[] = [];
14 |     const javaFiles = this.findJavaFiles(serviceRoot);
15 | 
16 |     for (const file of javaFiles) {
17 |       try {
18 |         const content = fs.readFileSync(file, 'utf8');
19 |         if (this.isJpaEntity(content)) {
20 |           const table = this.parseEntity(file, content);
21 |           if (table) tables.push(table);
22 |         }
23 |       } catch {
24 |         // skip
25 |       }
26 |     }
27 | 
28 |     return tables;
29 |   }
30 | 
31 |   private isJpaEntity(content: string): boolean {
32 |     return /@Entity/.test(content);
33 |   }
34 | 
35 |   private parseEntity(filePath: string, content: string): DatabaseTable | null {
36 |     const className = path.basename(filePath, '.java');
37 | 
38 |     // Determine table name
39 |     const tableName = this.extractTableName(content, className);
40 | 
41 |     // Extract columns
42 |     const columns = this.extractColumns(content);
43 | 
44 |     // Extract relationships
45 |     const relationships = this.extractRelationships(content, className);
46 | 
47 |     return {
48 |       tableName,
49 |       entityClass: className,
50 |       columns,
51 |       relationships,
52 |     };
53 |   }
54 | 
55 |   private extractTableName(content: string, className: string): string {
56 |     // @Table(name = "orders") or @Table("orders")
57 |     const m = content.match(/@Table\s*\(\s*(?:name\s*=\s*)?["']([^"']+)["']/);
58 |     if (m) return m[1];
59 | 
60 |     // Convert class name to snake_case
61 |     return className
62 |       .replace(/([A-Z])/g, '_$1')
63 |       .toLowerCase()
64 |       .replace(/^_/, '');
65 |   }
66 | 
67 |   private extractColumns(content: string): DatabaseColumn[] {
68 |     const columns: DatabaseColumn[] = [];
69 |     const lines = content.split('\n');
70 | 
71 |     for (let i = 0; i < lines.length; i++) {
72 |       const line = lines[i].trim();
73 | 
74 |       // Look for field declarations with @Column or @Id
75 |       const hasId = lines.slice(Math.max(0, i - 3), i + 1).some(l => /@Id/.test(l));
76 |       const columnAnnotation = lines
77 |         .slice(Math.max(0, i - 3), i + 1)
78 |         .find(l => /@Column/.test(l));
79 | 
80 |       // Parse field line: e.g. private UUID id; or private Integer customerId;
81 |       const fieldMatch = line.match(
82 |         /(?:private|protected|public)\s+([\w<>]+(?:\[\])?)\s+(\w+)\s*(?:=.*)?;/
83 |       );
84 | 
85 |       if (!fieldMatch) continue;
86 | 
87 |       const [, javaType, fieldName] = fieldMatch;
88 | 
89 |       // Skip non-column fields (relationships are handled separately)
90 |       if (
91 |         /@ManyToOne|@OneToMany|@ManyToMany|@OneToOne/.test(
92 |           lines.slice(Math.max(0, i - 3), i + 1).join(' ')
93 |         )
94 |       ) {
95 |         continue;
96 |       }
97 | 
98 |       // Skip collections that aren't direct columns
99 |       if (javaType.startsWith('List') || javaType.startsWith('Set') || javaType.startsWith('Collection')) {
100 |         continue;
101 |       }
102 | 
103 |       const isPrimaryKey = hasId || fieldName === 'id';
104 |       const columnName = this.extractColumnName(columnAnnotation, fieldName);
105 |       const sqlType = this.javaTypeToSql(javaType);
106 | 
107 |       const isNullable = !isPrimaryKey && !(columnAnnotation && /nullable\s*=\s*false/.test(columnAnnotation));
108 | 
109 |       columns.push({
110 |         name: columnName,
111 |         type: sqlType,
112 |         isPrimaryKey,
113 |         isNullable,
114 |         javaType,
115 |       });
116 |     }
117 | 
118 |     return columns;
119 |   }
120 | 
121 |   private extractColumnName(annotation: string | undefined, fieldName: string): string {
122 |     if (annotation) {
123 |       const m = annotation.match(/@Column\s*\(\s*(?:name\s*=\s*)?["']([^"']+)["']/);
124 |       if (m) return m[1];
125 |     }
126 | 
127 |     // Convert camelCase to snake_case
128 |     return fieldName
129 |       .replace(/([A-Z])/g, '_$1')
130 |       .toLowerCase()
131 |       .replace(/^_/, '');
132 |   }
133 | 
134 |   private javaTypeToSql(javaType: string): string {
135 |     const typeMap: Record<string, string> = {
136 |       'String': 'VARCHAR',
137 |       'Integer': 'INTEGER',
138 |       'int': 'INTEGER',
139 |       'Long': 'BIGINT',
140 |       'long': 'BIGINT',
141 |       'Double': 'DOUBLE',
142 |       'double': 'DOUBLE',
143 |       'Float': 'FLOAT',
144 |       'float': 'FLOAT',
145 |       'Boolean': 'BOOLEAN',
146 |       'boolean': 'BOOLEAN',
147 |       'UUID': 'UUID',
148 |       'LocalDate': 'DATE',
149 |       'LocalDateTime': 'TIMESTAMP',
150 |       'Date': 'TIMESTAMP',
151 |       'BigDecimal': 'DECIMAL',
152 |       'byte[]': 'BYTEA',
153 |     };
154 |     return typeMap[javaType] || javaType.toUpperCase();
155 |   }
156 | 
157 |   private extractRelationships(content: string, entityClass: string): DatabaseRelationship[] {
158 |     const relationships: DatabaseRelationship[] = [];
159 |     const lines = content.split('\n');
160 | 
161 |     for (let i = 0; i < lines.length; i++) {
162 |       const line = lines[i].trim();
163 | 
164 |       let relType: DatabaseRelationship['type'] | null = null;
165 |       if (/@ManyToOne/.test(line)) relType = 'ManyToOne';
166 |       else if (/@OneToMany/.test(line)) relType = 'OneToMany';
167 |       else if (/@ManyToMany/.test(line)) relType = 'ManyToMany';
168 |       else if (/@OneToOne/.test(line)) relType = 'OneToOne';
169 | 
170 |       if (!relType) continue;
171 | 
172 |       // Look at the next few lines for the field declaration
173 |       for (let j = i + 1; j < Math.min(i + 5, lines.length); j++) {
174 |         const fieldLine = lines[j].trim();
175 |         const fieldMatch = fieldLine.match(
176 |           /(?:private|protected|public)\s+(?:List|Set|Collection)?<?(\w+)>?\s+(\w+)\s*[;=]/
177 |         );
178 |         if (fieldMatch) {
179 |           relationships.push({
180 |             type: relType,
181 |             fromEntity: entityClass,
182 |             toEntity: fieldMatch[1],
183 |             fieldName: fieldMatch[2],
184 |           });
185 |           break;
186 |         }
187 |       }
188 |     }
189 | 
190 |     return relationships;
191 |   }
192 | 
