195 |     try {
196 |       const walk = (current: string) => {
197 |         const entries = fs.readdirSync(current, { withFileTypes: true });
198 |         for (const entry of entries) {
199 |           if (['target', '.git', 'node_modules', 'test'].includes(entry.name)) continue;
