135 |       path.join(serviceRoot, 'src', 'main', 'resources', 'application.yml'),
136 |     ];
137 | 
138 |     for (const configFile of configFiles) {
139 |       if (!fs.existsSync(configFile)) continue;
140 |       try {
141 |         const content = fs.readFileSync(configFile, 'utf8');
142 |         // Extract database name from JDBC URL: jdbc:postgresql://localhost:5432/orders_db
143 |         const jdbcMatch = content.match(/jdbc:[^:]+:\/\/[^/]+\/([a-zA-Z0-9_-]+)/);
144 |         if (jdbcMatch) {
145 |           databases.push(jdbcMatch[1]);
146 |         }
147 |         // Spring datasource url pattern
148 |         const urlMatch = content.match(/datasource[.\-]url.*\/([a-zA-Z0-9_-]+)(?:\?|$)/);
