161 |   private findJavaFiles(dir: string): string[] {
162 |     const results: string[] = [];
163 |     try {
164 |       const walk = (current: string) => {
165 |         const entries = fs.readdirSync(current, { withFileTypes: true });
166 |         for (const entry of entries) {
167 |           if (['target', '.git', 'node_modules'].includes(entry.name)) continue;
168 |           const full = path.join(current, entry.name);
169 |           if (entry.isDirectory()) walk(full);
170 |           else if (entry.name.endsWith('.java')) results.push(full);
171 |         }
172 |       };
173 |       walk(dir);
174 |     } catch {
