27 | export class ServiceItem extends vscode.TreeItem {
28 |   private context: ServiceContext;
29 | 
30 |   constructor(ctx: ServiceContext) {
31 |     super(ctx.identity.name, vscode.TreeItemCollapsibleState.Collapsed);
32 |     this.context = ctx;
33 | 
34 |     const statusIcon = this.getStatusIcon(ctx.status);
35 |     const commitShort = ctx.identity.commitHash.slice(0, 7);
36 | 
37 |     this.description = `${commitShort} · ${ctx.status}`;
38 |     this.iconPath = new vscode.ThemeIcon(statusIcon.icon, new vscode.ThemeColor(statusIcon.color));
39 |     this.tooltip = this.buildTooltip(ctx);
40 |     this.contextValue = 'service';
41 |   }
42 | 
43 |   getChildren(): ServiceItem[] {
44 |     const items: ServiceItem[] = [];
45 |     const ctx = this.context;
46 | 
47 |     // APIs section
48 |     if (ctx.apis.length > 0) {
49 |       const apisHeader = new ServiceItem(
50 |         { ...ctx, identity: { ...ctx.identity, name: `REST APIs (${ctx.apis.length})` } } as ServiceContext
51 |       );
52 |       apisHeader.collapsibleState = vscode.TreeItemCollapsibleState.None;
53 |       apisHeader.iconPath = new vscode.ThemeIcon('symbol-method');
54 |       apisHeader.description = ctx.apis.map(a => `${a.method} ${a.path}`).slice(0, 3).join(', ');
55 |       items.push(apisHeader);
56 |     }
57 | 
58 |     // Database section
59 |     if (ctx.database.length > 0) {
60 |       const dbHeader = new ServiceItem(
61 |         { ...ctx, identity: { ...ctx.identity, name: `Tables (${ctx.database.length})` } } as ServiceContext
62 |       );
63 |       dbHeader.collapsibleState = vscode.TreeItemCollapsibleState.None;
64 |       dbHeader.iconPath = new vscode.ThemeIcon('database');
65 |       dbHeader.description = ctx.database.map(t => t.tableName).join(', ');
66 |       items.push(dbHeader);
67 |     }
68 | 
69 |     // Dependencies
70 |     const restDeps = ctx.dependencies.filter(d => d.type === 'REST');
71 |     if (restDeps.length > 0) {
72 |       const depsHeader = new ServiceItem(
73 |         { ...ctx, identity: { ...ctx.identity, name: `Depends on (${restDeps.length})` } } as ServiceContext
74 |       );
75 |       depsHeader.collapsibleState = vscode.TreeItemCollapsibleState.None;
76 |       depsHeader.iconPath = new vscode.ThemeIcon('references');
77 |       depsHeader.description = restDeps.map(d => d.targetService).join(', ');
78 |       items.push(depsHeader);
79 |     }
80 | 
81 |     // Semantic summary
82 |     if (ctx.semanticSummary) {
83 |       const summaryItem = new ServiceItem(
84 |         { ...ctx, identity: { ...ctx.identity, name: 'Summary' } } as ServiceContext
85 |       );
86 |       summaryItem.collapsibleState = vscode.TreeItemCollapsibleState.None;
87 |       summaryItem.iconPath = new vscode.ThemeIcon('comment');
88 |       summaryItem.tooltip = ctx.semanticSummary;
89 |       summaryItem.description = ctx.semanticSummary.slice(0, 60) + (ctx.semanticSummary.length > 60 ? '…' : '');
90 |       items.push(summaryItem);
91 |     }
92 | 
93 |     return items;
94 |   }
95 | 
96 |   private getStatusIcon(status: string): { icon: string; color: string } {
97 |     switch (status) {
98 |       case 'Cached': return { icon: 'pass', color: 'testing.iconPassed' };
99 |       case 'Indexed': return { icon: 'check', color: 'testing.iconPassed' };
100 |       case 'Changed': return { icon: 'warning', color: 'testing.iconFailed' };
101 |       case 'Analyzing': return { icon: 'loading~spin', color: 'charts.blue' };
102 |       case 'Error': return { icon: 'error', color: 'testing.iconErrored' };
103 |       default: return { icon: 'circle-outline', color: 'foreground' };
104 |     }
105 |   }
106 | 
107 |   private buildTooltip(ctx: ServiceContext): string {
108 |     const lines = [
109 |       `Service: ${ctx.identity.name}`,
110 |       `Status:  ${ctx.status}`,
111 |       `Commit:  ${ctx.identity.commitHash.slice(0, 7)}`,
112 |       `Branch:  ${ctx.identity.branch}`,
113 |       `APIs:    ${ctx.apis.length}`,
114 |       `Tables:  ${ctx.database.length}`,
115 |       `Depends: ${ctx.dependencies.filter(d => d.type === 'REST').length} services`,
116 |       `Files:   ${ctx.fileCount}`,
117 |       `Analyzed: ${new Date(ctx.analyzedAt).toLocaleTimeString()}`,
118 |     ];
119 | 
120 |     if (ctx.semanticSummary) {
121 |       lines.push('', ctx.semanticSummary);
122 |     }
123 | 
124 |     return lines.join('\n');
125 |   }
126 | }
