4 | export class ImpactPanelProvider implements vscode.TreeDataProvider<vscode.TreeItem> {
5 |   private _onDidChangeTreeData = new vscode.EventEmitter<void>();
6 |   readonly onDidChangeTreeData = this._onDidChangeTreeData.event;
7 | 
8 |   private reports: ImpactReport[] = [];
9 | 
10 |   setImpacts(reports: ImpactReport[]) {
11 |     this.reports = reports;
12 |     this._onDidChangeTreeData.fire();
13 |   }
14 | 
15 |   getTreeItem(element: vscode.TreeItem): vscode.TreeItem {
16 |     return element;
17 |   }
18 | 
19 |   getChildren(element?: vscode.TreeItem): vscode.TreeItem[] {
20 |     if (!element) {
21 |       return this.buildRootItems();
22 |     }
23 |     return (element as any).__children ?? [];
24 |   }
25 | 
26 |   private buildRootItems(): vscode.TreeItem[] {
27 |     if (this.reports.length === 0) {
28 |       const empty = new vscode.TreeItem(
29 |         'No impact data — click "Analyze Changes"',
30 |         vscode.TreeItemCollapsibleState.None
31 |       );
32 |       empty.iconPath = new vscode.ThemeIcon('info');
33 |       return [empty];
34 |     }
35 | 
36 |     const items: vscode.TreeItem[] = [];
37 | 
38 |     for (const report of this.reports) {
39 |       const highCount = report.impacts.filter(i => i.severity === 'HIGH').length;
40 |       const medCount = report.impacts.filter(i => i.severity === 'MEDIUM').length;
41 |       const lowCount = report.impacts.filter(i => i.severity === 'LOW').length;
42 | 
43 |       const reportItem = new vscode.TreeItem(
44 |         `${report.serviceId}`,
45 |         vscode.TreeItemCollapsibleState.Expanded
46 |       );
47 |       reportItem.description = `${report.change.slice(0, 50)}`;
48 |       reportItem.iconPath = new vscode.ThemeIcon('diff', new vscode.ThemeColor('charts.orange'));
49 | 
50 |       const children: vscode.TreeItem[] = [];
51 | 
52 |       // Summary
53 |       const summaryItem = new vscode.TreeItem(
54 |         `${highCount > 0 ? `⚠ ${highCount} HIGH` : ''} ${medCount > 0 ? `${medCount} MEDIUM` : ''} ${lowCount > 0 ? `${lowCount} LOW` : ''}`.trim() || 'No impacts',
55 |         vscode.TreeItemCollapsibleState.None
56 |       );
57 |       summaryItem.iconPath = new vscode.ThemeIcon(highCount > 0 ? 'warning' : 'info');
58 |       children.push(summaryItem);
59 | 
60 |       // Interpretation
61 |       if (report.changeInterpretation) {
62 |         const interpItem = new vscode.TreeItem(report.changeInterpretation, vscode.TreeItemCollapsibleState.None);
63 |         interpItem.iconPath = new vscode.ThemeIcon('comment');
64 |         children.push(interpItem);
65 |       }
66 | 
67 |       // Individual impacts
68 |       for (const impact of report.impacts) {
69 |         const impactItem = this.buildImpactItem(impact);
70 |         children.push(impactItem);
71 |       }
72 | 
73 |       // Migration steps
74 |       if (report.migrationRecommendations.length > 0) {
75 |         const migHeader = new vscode.TreeItem('Migration Recommendations', vscode.TreeItemCollapsibleState.None);
76 |         migHeader.iconPath = new vscode.ThemeIcon('checklist');
77 |         migHeader.description = report.migrationRecommendations.length + ' steps';
78 |         migHeader.tooltip = report.migrationRecommendations.join('\n');
79 |         children.push(migHeader);
80 |       }
81 | 
82 |       (reportItem as any).__children = children;
83 |       items.push(reportItem);
84 |     }
85 | 
86 |     return items;
87 |   }
88 | 
89 |   private buildImpactItem(impact: ImpactEntry): vscode.TreeItem {
90 |     const icon = impact.severity === 'HIGH' ? 'error' : impact.severity === 'MEDIUM' ? 'warning' : 'info';
91 |     const color = impact.severity === 'HIGH'
92 |       ? 'testing.iconErrored'
93 |       : impact.severity === 'MEDIUM'
94 |       ? 'charts.orange'
95 |       : 'charts.blue';
96 | 
97 |     const item = new vscode.TreeItem(
98 |       `${impact.severity}: ${impact.component}`,
99 |       vscode.TreeItemCollapsibleState.None
100 |     );
101 |     item.iconPath = new vscode.ThemeIcon(icon, new vscode.ThemeColor(color));
102 |     item.description = impact.reason.slice(0, 60) + (impact.reason.length > 60 ? '…' : '');
103 |     item.tooltip = [
104 |       `Severity: ${impact.severity}`,
105 |       `Component: ${impact.component}`,
106 |       ``,
107 |       `Reason: ${impact.reason}`,
108 |       impact.recommendedAction ? `\nAction: ${impact.recommendedAction}` : '',
109 |     ].join('\n');
110 | 
111 |     return item;
112 |   }
113 | }
