294 | 
295 |   function svgNS() { return 'http://www.w3.org/2000/svg'; }
296 |   function el(tag, attrs = {}, text = '') {
297 |     const e = document.createElementNS(svgNS(), tag);
298 |     Object.entries(attrs).forEach(([k, v]) => e.setAttribute(k, v));
299 |     if (text) e.textContent = text;
