303 |   // ── Layout ────────────────────────────────────────────────────────────
304 |   function computeLayout(nodes, edges) {
305 |     const W = svg.clientWidth || 800;
306 |     const H = svg.clientHeight || 600;
307 |     const positions = {};
308 | 
309 |     // Separate services and databases
310 |     const services = nodes.filter(n => n.type === 'SERVICE');
311 |     const databases = nodes.filter(n => n.type === 'DATABASE');
312 | 
313 |     // Arrange services in a circle in top portion
314 |     const centerX = W / 2;
315 |     const centerY = H * 0.38;
316 |     const radius = Math.min(W, H) * 0.28;
317 | 
318 |     if (services.length === 1) {
319 |       positions[services[0].id] = { x: centerX, y: centerY };
320 |     } else {
321 |       services.forEach((n, i) => {
322 |         const angle = (i / services.length) * 2 * Math.PI - Math.PI / 2;
323 |         positions[n.id] = {
324 |           x: centerX + radius * Math.cos(angle),
325 |           y: centerY + radius * Math.sin(angle),
326 |         };
327 |       });
328 |     }
329 | 
330 |     // Position databases below their owner service
331 |     databases.forEach((db, i) => {
332 |       // Find the service that owns this db
333 |       const ownerEdge = edges.find(e => e.target === db.id && e.type === 'SERVICE_USES_DATABASE');
334 |       if (ownerEdge && positions[ownerEdge.source]) {
335 |         const ownerPos = positions[ownerEdge.source];
336 |         positions[db.id] = {
337 |           x: ownerPos.x,
338 |           y: ownerPos.y + 130 + (i % 2 === 0 ? 0 : 20),
339 |         };
340 |       } else {
341 |         positions[db.id] = {
342 |           x: 80 + i * 160,
343 |           y: H * 0.78,
344 |         };
345 |       }
346 |     });
347 | 
348 |     return positions;
349 |   }
