356 |     if (!data || !data.nodes) return;
357 | 
358 |     nodePositions = computeLayout(data.nodes, data.edges || []);
359 | 
360 |     // Update header
361 |     const svcCount = data.nodes.filter(n => n.type === 'SERVICE').length;
362 |     const dbCount = data.nodes.filter(n => n.type === 'DATABASE').length;
363 |     document.getElementById('header-info').textContent =
364 |       svcCount + ' services · ' + dbCount + ' databases · ' + (data.edges || []).length + ' edges · HEAD: ' +
365 |       (data.generatedAt ? new Date(data.generatedAt).toLocaleTimeString() : '');
366 | 
367 |     // Draw edges first
368 |     (data.edges || []).forEach(edge => {
369 |       const src = nodePositions[edge.source];
370 |       const tgt = nodePositions[edge.target];
371 |       if (!src || !tgt) return;
372 | 
373 |       const srcNode = data.nodes.find(n => n.id === edge.source);
374 |       const tgtNode = data.nodes.find(n => n.id === edge.target);
375 | 
376 |       const {sx, sy, tx, ty} = getEdgePoints(src, tgt, srcNode, tgtNode);
377 | 
378 |       const path = el('path', {
379 |         class: 'edge ' + edge.type,
380 |         d: \`M\${sx},\${sy} C\${sx},\${(sy+ty)/2} \${tx},\${(sy+ty)/2} \${tx},\${ty}\`,
381 |         'marker-end': edge.type === 'SERVICE_USES_DATABASE' ? 'url(#arrowhead-purple)' : 'url(#arrowhead-blue)',
382 |         stroke: edge.type === 'SERVICE_USES_DATABASE' ? '#9575cd' : '#4fc3f7',
383 |       });
