399 |   function getEdgePoints(src, tgt, srcNode, tgtNode) {
400 |     let sx = src.x, sy = src.y, tx = tgt.x, ty = tgt.y;
401 |     const dx = tgt.x - src.x;
402 |     const dy = tgt.y - src.y;
403 |     const dist = Math.sqrt(dx*dx + dy*dy) || 1;
404 | 
405 |     // Adjust for node shapes
406 |     const srcR = srcNode && srcNode.type === 'SERVICE' ? SERVICE_RADIUS : 18;
407 |     const tgtR = tgtNode && tgtNode.type === 'SERVICE' ? SERVICE_RADIUS : 18;
408 | 
409 |     sx = src.x + (dx / dist) * srcR;
410 |     sy = src.y + (dy / dist) * srcR;
411 |     tx = tgt.x - (dx / dist) * tgtR;
412 |     ty = tgt.y - (dy / dist) * tgtR;
413 | 
414 |     return {sx, sy, tx, ty};
415 |   }
