import * as fs from 'fs';
import * as path from 'path';
import Database from 'better-sqlite3';
import { ServiceContext } from '../models/types';

/**
 * SQLite-backed persistent cache for ServiceContext objects.
 * Cache key: serviceId + branch + commitHash
 */
export class ContextCache {
  private db: Database.Database;
  private dbPath: string;

  constructor(cacheDir: string) {
    fs.mkdirSync(cacheDir, { recursive: true });
    this.dbPath = path.join(cacheDir, 'context-cache.db');
    this.db = new Database(this.dbPath);
    this.initialize();
  }

  private initialize(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS service_context (
        service_id TEXT NOT NULL,
        branch TEXT NOT NULL,
        commit_hash TEXT NOT NULL,
        context_json TEXT NOT NULL,
        analyzed_at TEXT NOT NULL,
        PRIMARY KEY (service_id, branch, commit_hash)
      );

      CREATE TABLE IF NOT EXISTS cache_metadata (
        service_id TEXT PRIMARY KEY,
        last_analyzed_commit TEXT,
        previous_commit TEXT,
        last_analyzed_at TEXT
      );
    `);
  }

  /**
   * Get cached context for a service at a specific commit.
   */
  get(serviceId: string, branch: string, commitHash: string): ServiceContext | null {
    const row = this.db
      .prepare(
        'SELECT context_json FROM service_context WHERE service_id = ? AND branch = ? AND commit_hash = ?'
      )
      .get(serviceId, branch, commitHash) as { context_json: string } | undefined;

    if (!row) return null;

    try {
      return JSON.parse(row.context_json) as ServiceContext;
    } catch {
      return null;
    }
  }

  /**
   * Store a ServiceContext in the cache.
   */
  set(context: ServiceContext): void {
    const { serviceId, branch, commitHash } = context.identity;

    this.db
      .prepare(
        `INSERT OR REPLACE INTO service_context 
         (service_id, branch, commit_hash, context_json, analyzed_at) 
         VALUES (?, ?, ?, ?, ?)`
      )
      .run(serviceId, branch, commitHash, JSON.stringify(context), context.analyzedAt);

    // Update metadata
    const existing = this.db
      .prepare('SELECT last_analyzed_commit FROM cache_metadata WHERE service_id = ?')
      .get(serviceId) as { last_analyzed_commit: string } | undefined;

    this.db
      .prepare(
        `INSERT OR REPLACE INTO cache_metadata 
         (service_id, last_analyzed_commit, previous_commit, last_analyzed_at) 
         VALUES (?, ?, ?, ?)`
      )
      .run(
        serviceId,
        commitHash,
        existing?.last_analyzed_commit ?? null,
        new Date().toISOString()
      );
  }

  /**
   * Get the last analyzed commit hash for a service.
   */
  getLastAnalyzedCommit(serviceId: string): string | null {
    const row = this.db
      .prepare('SELECT last_analyzed_commit FROM cache_metadata WHERE service_id = ?')
      .get(serviceId) as { last_analyzed_commit: string } | undefined;
    return row?.last_analyzed_commit ?? null;
  }

  /**
   * Get the previous commit (before the last analysis) for incremental diff.
   */
  getPreviousCommit(serviceId: string): string | null {
    const row = this.db
      .prepare('SELECT previous_commit FROM cache_metadata WHERE service_id = ?')
      .get(serviceId) as { previous_commit: string } | undefined;
    return row?.previous_commit ?? null;
  }

  /**
   * Check if we have a cached context for the current commit.
   */
  isCached(serviceId: string, branch: string, commitHash: string): boolean {
    return this.get(serviceId, branch, commitHash) !== null;
  }

  /**
   * List all cached service IDs with their latest commit info.
   */
  listCached(): Array<{ serviceId: string; commitHash: string; analyzedAt: string }> {
    return this.db
      .prepare(
        `SELECT cm.service_id as serviceId, cm.last_analyzed_commit as commitHash, cm.last_analyzed_at as analyzedAt
         FROM cache_metadata cm`
      )
      .all() as Array<{ serviceId: string; commitHash: string; analyzedAt: string }>;
  }

  /**
   * Invalidate cache for a service.
   */
  invalidate(serviceId: string): void {
    this.db.prepare('DELETE FROM service_context WHERE service_id = ?').run(serviceId);
    this.db.prepare('DELETE FROM cache_metadata WHERE service_id = ?').run(serviceId);
  }

  /**
   * Estimate token savings based on context size.
   */
  estimateTokenSavings(context: ServiceContext): number {
    const json = JSON.stringify(context);
    // Rough estimate: 4 chars per token
    return Math.floor(json.length / 4);
  }

  close(): void {
    this.db.close();
  }
}

