6 | /**
7 |  * Discovers microservice directories within a workspace root.
8 |  * Looks for directories containing pom.xml or build.gradle (Spring Boot indicators).
9 |  */
10 | export class WorkspaceScanner {
11 |   private workspaceRoot: string;
12 | 
13 |   constructor(workspaceRoot: string) {
14 |     this.workspaceRoot = workspaceRoot;
15 |   }
16 | 
17 |   async discoverServices(): Promise<DiscoveredService[]> {
18 |     const services: DiscoveredService[] = [];
19 |     const candidates = this.findServiceDirectories(this.workspaceRoot);
20 | 
21 |     for (const candidate of candidates) {
22 |       const service = await this.analyzeDirectory(candidate);
23 |       if (service) {
24 |         services.push(service);
25 |       }
26 |     }
27 | 
28 |     return services;
29 |   }
30 | 
31 |   private findServiceDirectories(root: string): string[] {
32 |     const results: string[] = [];
33 | 
34 |     // Check root itself
35 |     if (this.isServiceDirectory(root)) {
36 |       results.push(root);
37 |       return results; // Don't recurse into a service dir
38 |     }
39 | 
40 |     try {
41 |       const entries = fs.readdirSync(root, { withFileTypes: true });
42 |       for (const entry of entries) {
43 |         if (!entry.isDirectory()) continue;
44 |         if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
45 | 
46 |         const fullPath = path.join(root, entry.name);
47 |         if (this.isServiceDirectory(fullPath)) {
48 |           results.push(fullPath);
49 |         } else {
50 |           // Check one level deeper (monorepo style)
51 |           try {
52 |             const sub = fs.readdirSync(fullPath, { withFileTypes: true });
53 |             for (const subEntry of sub) {
54 |               if (!subEntry.isDirectory()) continue;
55 |               if (subEntry.name.startsWith('.')) continue;
56 |               const subPath = path.join(fullPath, subEntry.name);
57 |               if (this.isServiceDirectory(subPath)) {
58 |                 results.push(subPath);
59 |               }
60 |             }
61 |           } catch {
62 |             // ignore unreadable
63 |           }
64 |         }
65 |       }
66 |     } catch {
67 |       // ignore
68 |     }
69 | 
70 |     return results;
71 |   }
72 | 
73 |   private isServiceDirectory(dir: string): boolean {
74 |     return (
75 |       fs.existsSync(path.join(dir, 'pom.xml')) ||
76 |       fs.existsSync(path.join(dir, 'build.gradle')) ||
77 |       fs.existsSync(path.join(dir, 'build.gradle.kts'))
78 |     );
79 |   }
80 | 
81 |   private async analyzeDirectory(dirPath: string): Promise<DiscoveredService | null> {
82 |     const name = path.basename(dirPath);
83 |     const serviceId = this.generateServiceId(dirPath);
84 | 
85 |     let repository = dirPath;
86 |     let branch = 'main';
87 |     let commitHash = 'unknown';
88 |     let isGitRepo = false;
89 | 
90 |     try {
91 |       // Find git root
92 |       const gitRoot = execSync('git rev-parse --show-toplevel', {
93 |         cwd: dirPath,
94 |         encoding: 'utf8',
95 |         stdio: ['pipe', 'pipe', 'pipe'],
96 |       }).trim();
97 | 
98 |       repository = gitRoot;
99 |       isGitRepo = true;
100 | 
101 |       branch = execSync('git rev-parse --abbrev-ref HEAD', {
102 |         cwd: dirPath,
103 |         encoding: 'utf8',
104 |         stdio: ['pipe', 'pipe', 'pipe'],
105 |       }).trim();
106 | 
107 |       commitHash = execSync('git rev-parse HEAD', {
108 |         cwd: dirPath,
109 |         encoding: 'utf8',
110 |         stdio: ['pipe', 'pipe', 'pipe'],
111 |       }).trim();
112 |     } catch {
113 |       // Not a git repo or git not available
114 |     }
115 | 
116 |     // Detect stack
117 |     const detectedStack = this.isSpringBootService(dirPath) ? 'spring-boot' : 'unknown';
118 | 
119 |     return {
120 |       serviceId,
121 |       name,
122 |       rootPath: dirPath,
123 |       repository,
124 |       branch,
125 |       commitHash,
126 |       isGitRepo,
127 |       detectedStack,
128 |     };
129 |   }
130 | 
131 |   private isSpringBootService(dir: string): boolean {
132 |     // Check pom.xml for spring-boot dependency
133 |     const pomPath = path.join(dir, 'pom.xml');
134 |     if (fs.existsSync(pomPath)) {
135 |       const content = fs.readFileSync(pomPath, 'utf8');
136 |       return content.includes('spring-boot') || content.includes('springframework');
137 |     }
138 |     return false;
139 |   }
140 | 
141 |   generateServiceId(dirPath: string): string {
142 |     return path.basename(dirPath).toLowerCase().replace(/[^a-z0-9-]/g, '-');
143 |   }
144 | 
145 |   countFiles(dirPath: string, extensions: string[] = ['.java']): number {
146 |     let count = 0;
147 |     try {
148 |       const walk = (dir: string) => {
149 |         const entries = fs.readdirSync(dir, { withFileTypes: true });
150 |         for (const entry of entries) {
151 |           if (entry.name.startsWith('.') || entry.name === 'node_modules' || entry.name === 'target') continue;
152 |           const full = path.join(dir, entry.name);
153 |           if (entry.isDirectory()) {
154 |             walk(full);
155 |           } else if (extensions.some(ext => entry.name.endsWith(ext))) {
156 |             count++;
157 |           }
158 |         }
159 |       };
160 |       walk(dirPath);
161 |     } catch {
162 |       // ignore
163 |     }
164 |     return count;
165 |   }
