5 | /**
6 |  * Parses Spring Boot Java source files to extract REST API endpoints.
7 |  * Uses regex-based parsing (no full Java AST required for hackathon).
8 |  */
9 | export class SpringApiParser {
10 |   /**
11 |    * Parse all Java files in a service directory and extract endpoints.
12 |    */
13 |   parseService(serviceRoot: string): ApiEndpoint[] {
14 |     const endpoints: ApiEndpoint[] = [];
15 |     const javaFiles = this.findJavaFiles(serviceRoot);
16 | 
17 |     for (const file of javaFiles) {
18 |       try {
19 |         const content = fs.readFileSync(file, 'utf8');
20 |         if (this.isRestController(content)) {
21 |           const fileEndpoints = this.parseController(file, content);
22 |           endpoints.push(...fileEndpoints);
23 |         }
24 |       } catch {
25 |         // skip unreadable files
26 |       }
27 |     }
28 | 
29 |     return endpoints;
30 |   }
31 | 
32 |   private isRestController(content: string): boolean {
33 |     return /@RestController/.test(content) || /@Controller/.test(content);
34 |   }
35 | 
36 |   private parseController(filePath: string, content: string): ApiEndpoint[] {
37 |     const endpoints: ApiEndpoint[] = [];
38 |     const controllerName = path.basename(filePath, '.java');
39 | 
40 |     // Extract class-level @RequestMapping
41 |     const classMapping = this.extractClassMapping(content);
42 | 
43 |     // Extract all handler methods
44 |     const lines = content.split('\n');
45 |     const methods = this.extractHandlerMethods(lines, classMapping, controllerName);
46 |     endpoints.push(...methods);
47 | 
48 |     return endpoints;
49 |   }
50 | 
51 |   private extractClassMapping(content: string): string {
52 |     const match = content.match(/@RequestMapping\s*\(\s*(?:value\s*=\s*)?["']([^"']+)["']/);
53 |     return match ? match[1] : '';
54 |   }
55 | 
56 |   private extractHandlerMethods(
57 |     lines: string[],
58 |     classPath: string,
59 |     controllerName: string
60 |   ): ApiEndpoint[] {
61 |     const endpoints: ApiEndpoint[] = [];
62 |     const httpMethodAnnotations = [
63 |       { pattern: /@GetMapping/, method: 'GET' as const },
64 |       { pattern: /@PostMapping/, method: 'POST' as const },
65 |       { pattern: /@PutMapping/, method: 'PUT' as const },
66 |       { pattern: /@DeleteMapping/, method: 'DELETE' as const },
67 |       { pattern: /@PatchMapping/, method: 'PATCH' as const },
68 |     ];
69 | 
70 |     for (let i = 0; i < lines.length; i++) {
71 |       const line = lines[i].trim();
72 | 
73 |       for (const { pattern, method } of httpMethodAnnotations) {
74 |         if (!pattern.test(line)) continue;
75 | 
76 |         // Extract path from annotation
77 |         const annotationPath = this.extractAnnotationPath(line, lines, i);
78 |         const fullPath = this.joinPaths(classPath, annotationPath);
79 | 
80 |         // Look ahead for method signature
81 |         const methodInfo = this.extractMethodSignature(lines, i);
82 | 
83 |         endpoints.push({
84 |           method,
85 |           path: fullPath || '/',
86 |           controller: controllerName,
87 |           handlerMethod: methodInfo.name,
88 |           requestModel: methodInfo.requestModel,
89 |           responseModel: methodInfo.responseModel,
90 |         });
91 |         break;
92 |       }
93 | 
94 |       // Also handle @RequestMapping on methods
95 |       if (/@RequestMapping\s*\(/.test(line)) {
96 |         const httpMethod = this.extractRequestMappingMethod(line);
97 |         if (httpMethod) {
98 |           const annotationPath = this.extractAnnotationPath(line, lines, i);
99 |           const fullPath = this.joinPaths(classPath, annotationPath);
100 |           const methodInfo = this.extractMethodSignature(lines, i);
101 | 
102 |           endpoints.push({
103 |             method: httpMethod,
104 |             path: fullPath || '/',
105 |             controller: controllerName,
106 |             handlerMethod: methodInfo.name,
107 |             requestModel: methodInfo.requestModel,
108 |             responseModel: methodInfo.responseModel,
109 |           });
110 |         }
111 |       }
112 |     }
113 | 
114 |     return endpoints;
115 |   }
