117 |   private extractAnnotationPath(line: string, lines: string[], index: number): string {
118 |     // Check current line for path in annotation
119 |     let annotationText = line;
120 | 
121 |     // If annotation spans multiple lines, collect them
122 |     if (line.includes('(') && !line.includes(')')) {
123 |       for (let j = index + 1; j < Math.min(index + 5, lines.length); j++) {
124 |         annotationText += ' ' + lines[j].trim();
125 |         if (lines[j].includes(')')) break;
126 |       }
127 |     }
128 | 
129 |     // Try to extract path value
130 |     const patterns = [
131 |       /(?:value\s*=\s*)?["']([^"']+)["']/,
132 |       /\{\s*["']([^"']+)["']/,
133 |     ];
134 | 
135 |     for (const p of patterns) {
136 |       const m = annotationText.match(p);
137 |       if (m) return m[1];
138 |     }
139 | 
140 |     return '';
141 |   }
142 | 
143 |   private extractRequestMappingMethod(line: string): ApiEndpoint['method'] | null {
144 |     const m = line.match(/method\s*=\s*RequestMethod\.(\w+)/);
145 |     if (!m) return null;
146 |     const method = m[1].toUpperCase();
147 |     if (['GET', 'POST', 'PUT', 'DELETE', 'PATCH'].includes(method)) {
148 |       return method as ApiEndpoint['method'];
149 |     }
150 |     return null;
151 |   }
152 | 
153 |   private extractMethodSignature(
154 |     lines: string[],
155 |     annotationIndex: number
156 |   ): { name: string; requestModel?: string; responseModel?: string } {
157 |     // Look at lines after the annotation for the method signature
158 |     for (let i = annotationIndex + 1; i < Math.min(annotationIndex + 10, lines.length); i++) {
159 |       const line = lines[i].trim();
160 | 
161 |       // Skip other annotations
162 |       if (line.startsWith('@')) continue;
163 |       if (line.length === 0) continue;
164 | 
165 |       // Try to parse method signature
166 |       // e.g.: public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest request)
167 |       const methodMatch = line.match(
168 |         /(?:public|protected|private)?\s+(?:[\w<>\[\],\s]+)\s+(\w+)\s*\(/
169 |       );
170 |       if (methodMatch) {
171 |         const name = methodMatch[1];
172 |         const responseModel = this.extractResponseType(line);
173 |         const requestModel = this.extractRequestBodyType(line);
174 |         return { name, requestModel, responseModel };
175 |       }
176 |     }
177 | 
178 |     return { name: 'unknown' };
179 |   }
180 | 
181 |   private extractResponseType(methodLine: string): string | undefined {
182 |     // ResponseEntity<Foo> or List<Foo> or Foo
183 |     const m = methodLine.match(/ResponseEntity\s*<([^>]+)>/);
184 |     if (m) return this.cleanGenericType(m[1]);
185 | 
186 |     const m2 = methodLine.match(/(?:public|protected|private)\s+([\w<>\[\]]+)\s+\w+\s*\(/);
187 |     if (m2 && !['void', 'String', 'boolean', 'int', 'long'].includes(m2[1])) {
188 |       return this.cleanGenericType(m2[1]);
189 |     }
190 | 
191 |     return undefined;
192 |   }
193 | 
194 |   private extractRequestBodyType(methodLine: string): string | undefined {
195 |     const m = methodLine.match(/@RequestBody\s+(\w+)/);
196 |     return m ? m[1] : undefined;
197 |   }
198 | 
199 |   private cleanGenericType(type: string): string {
200 |     return type.replace(/\s/g, '').trim();
201 |   }
202 | 
203 |   private joinPaths(...parts: string[]): string {
204 |     const joined = parts
205 |       .filter(p => p)
206 |       .join('/')
207 |       .replace(/\/+/g, '/');
208 |     return joined.startsWith('/') ? joined : '/' + joined;
209 |   }
210 | 
211 |   private findJavaFiles(dir: string): string[] {
212 |     const results: string[] = [];
213 |     try {
214 |       const walk = (current: string) => {
215 |         const entries = fs.readdirSync(current, { withFileTypes: true });
216 |         for (const entry of entries) {
217 |           if (entry.name === 'target' || entry.name === '.git' || entry.name === 'node_modules') continue;
218 |           const full = path.join(current, entry.name);
219 |           if (entry.isDirectory()) {
220 |             walk(full);
221 |           } else if (entry.name.endsWith('.java')) {
222 |             results.push(full);
223 |           }
224 |         }
225 |       };
226 |       walk(dir);
227 |     } catch {
228 |       // ignore
229 |     }
230 |     return results;
231 |   }
232 | }
