5 | /**
6 |  * Git operations for commit detection and diff analysis.
7 |  */
8 | export class GitAnalyzer {
9 |   private repoPath: string;
10 | 
11 |   constructor(repoPath: string) {
12 |     this.repoPath = repoPath;
13 |   }
14 | 
15 |   /**
16 |    * Get current HEAD commit hash (short = 7 chars, long = 40 chars).
17 |    */
18 |   getHead(short = true): string {
19 |     try {
20 |       return execSync(`git rev-parse ${short ? '--short' : ''} HEAD`, {
21 |         cwd: this.repoPath,
22 |         encoding: 'utf8',
23 |         stdio: ['pipe', 'pipe', 'pipe'],
24 |       }).trim();
25 |     } catch {
26 |       return 'unknown';
27 |     }
28 |   }
29 | 
30 |   /**
31 |    * Get current branch name.
32 |    */
33 |   getBranch(): string {
34 |     try {
35 |       return execSync('git rev-parse --abbrev-ref HEAD', {
36 |         cwd: this.repoPath,
37 |         encoding: 'utf8',
38 |         stdio: ['pipe', 'pipe', 'pipe'],
39 |       }).trim();
40 |     } catch {
41 |       return 'main';
42 |     }
43 |   }
44 | 
45 |   /**
46 |    * Get list of changed files between two commits.
47 |    */
48 |   getChangedFiles(oldCommit: string, newCommit: string): ChangedFile[] {
49 |     try {
50 |       const output = execSync(`git diff --name-status ${oldCommit} ${newCommit}`, {
51 |         cwd: this.repoPath,
52 |         encoding: 'utf8',
53 |         stdio: ['pipe', 'pipe', 'pipe'],
54 |       }).trim();
55 | 
56 |       if (!output) return [];
57 | 
58 |       return output.split('\n').map(line => {
59 |         const [status, ...rest] = line.split('\t');
60 |         const filePath = rest[rest.length - 1];
61 |         const changeType = this.mapStatus(status);
62 |         const category = this.classifyFile(filePath);
63 |         return { path: filePath, category, changeType };
64 |       }).filter(f => f.path);
65 |     } catch {
66 |       return [];
67 |     }
68 |   }
69 | 
70 |   /**
71 |    * Get all Java files changed since a specific commit.
72 |    */
73 |   getChangedJavaFiles(oldCommit: string, newCommit: string): string[] {
74 |     return this.getChangedFiles(oldCommit, newCommit)
75 |       .filter(f => f.path.endsWith('.java'))
76 |       .map(f => f.path);
77 |   }
78 | 
79 |   /**
80 |    * Classify a file path into a category.
81 |    */
82 |   classifyFile(filePath: string): FileCategory {
83 |     const lower = filePath.toLowerCase();
84 |     const basename = path.basename(lower);
85 | 
86 |     if (basename.endsWith('controller.java')) return 'API';
87 |     if (lower.includes('/controller/')) return 'API';
88 |     if (basename.endsWith('entity.java')) return 'ENTITY';
89 |     if (lower.includes('/entity/') || lower.includes('/entities/')) return 'ENTITY';
90 |     if (lower.includes('/model/') || basename.endsWith('dto.java') || basename.endsWith('request.java') || basename.endsWith('response.java')) return 'DTO';
91 |     if (lower.includes('/service/') && basename.endsWith('service.java')) return 'SERVICE';
92 |     if (lower.includes('application.properties') || lower.includes('application.yml') || basename === 'pom.xml') return 'CONFIG';
93 |     if (basename.endsWith('.java')) return 'SERVICE';
94 |     return 'UNKNOWN';
95 |   }
96 | 
97 |   private mapStatus(status: string): 'added' | 'modified' | 'deleted' {
98 |     if (status.startsWith('A')) return 'added';
99 |     if (status.startsWith('D')) return 'deleted';
100 |     return 'modified';
101 |   }
102 | 
103 |   /**
104 |    * Get git log for recent commits.
105 |    */
106 |   getRecentCommits(count = 10): Array<{ hash: string; message: string; author: string; date: string }> {
107 |     try {
108 |       const output = execSync(`git log --oneline -${count} --format="%H|%s|%an|%ai"`, {
109 |         cwd: this.repoPath,
110 |         encoding: 'utf8',
111 |         stdio: ['pipe', 'pipe', 'pipe'],
112 |       }).trim();
113 | 
114 |       return output.split('\n').filter(Boolean).map(line => {
115 |         const [hash, message, author, date] = line.split('|');
116 |         return { hash, message, author, date };
117 |       });
118 |     } catch {
119 |       return [];
120 |     }
121 |   }
122 | 
123 |   /**
124 |    * Check if given commit hash is valid.
125 |    */
126 |   isValidCommit(hash: string): boolean {
127 |     try {
128 |       execSync(`git rev-parse --verify ${hash}`, {
129 |         cwd: this.repoPath,
130 |         encoding: 'utf8',
131 |         stdio: ['pipe', 'pipe', 'pipe'],
132 |       });
133 |       return true;
134 |     } catch {
135 |       return false;
136 |     }
137 |   }
138 | }
