9 | /**
10 |  * Builds and maintains the System Context Graph from ServiceContexts.
11 |  */
12 | export class ContextGraphBuilder {
13 |   /**
14 |    * Build a complete system graph from all service contexts.
15 |    */
16 |   build(services: ServiceContext[]): SystemContextGraph {
17 |     const nodes: GraphNode[] = [];
18 |     const edges: GraphEdge[] = [];
19 |     const dbNodes = new Map<string, GraphNode>();
20 | 
21 |     // Create service nodes
22 |     for (const svc of services) {
23 |       nodes.push({
24 |         id: svc.identity.serviceId,
25 |         type: 'SERVICE',
26 |         label: svc.identity.name,
27 |         data: svc,
28 |       });
29 | 
30 |       // Create database nodes for each table group
31 |       const dbNames = this.inferDatabaseNames(svc);
32 |       for (const dbName of dbNames) {
33 |         if (!dbNodes.has(dbName)) {
34 |           const dbNodeData: DatabaseNodeData = {
35 |             name: dbName,
36 |             tables: svc.database,
37 |             ownerServiceId: svc.identity.serviceId,
38 |           };
39 |           const dbNode: GraphNode = {
40 |             id: `db:${dbName}`,
41 |             type: 'DATABASE',
42 |             label: dbName,
43 |             data: dbNodeData,
44 |           };
45 |           dbNodes.set(dbName, dbNode);
46 |         }
47 | 
48 |         // Add Service → Database edge
49 |         edges.push({
50 |           id: `${svc.identity.serviceId}->db:${dbName}`,
51 |           type: 'SERVICE_USES_DATABASE',
52 |           source: svc.identity.serviceId,
53 |           target: `db:${dbName}`,
54 |           label: 'uses',
55 |         });
56 |       }
57 |     }
58 | 
59 |     // Add database nodes to main nodes array
60 |     nodes.push(...dbNodes.values());
61 | 
62 |     // Create service → service dependency edges
63 |     for (const svc of services) {
64 |       for (const dep of svc.dependencies) {
65 |         // Find target service node
66 |         const targetId = this.resolveServiceId(dep.targetService, services);
67 |         if (targetId) {
68 |           const edgeId = `${svc.identity.serviceId}->${targetId}`;
69 |           // Avoid duplicate edges
70 |           if (!edges.find(e => e.id === edgeId)) {
71 |             edges.push({
72 |               id: edgeId,
73 |               type: 'SERVICE_DEPENDS_ON_SERVICE',
74 |               source: svc.identity.serviceId,
75 |               target: targetId,
76 |               label: 'depends on',
77 |             });
78 |           }
79 |         }
80 |       }
81 |     }
82 | 
83 |     return {
84 |       nodes,
85 |       edges,
86 |       generatedAt: new Date().toISOString(),
87 |     };
88 |   }
89 | 
90 |   /**
91 |    * Apply impact highlighting to graph nodes.
92 |    */
93 |   applyImpact(
94 |     graph: SystemContextGraph,
95 |     impacts: Array<{ component: string; severity: 'HIGH' | 'MEDIUM' | 'LOW'; reason: string }>
96 |   ): SystemContextGraph {
97 |     const updatedNodes = graph.nodes.map(node => {
98 |       const impact = impacts.find(
99 |         i =>
100 |           i.component.toLowerCase().includes(node.label.toLowerCase()) ||
101 |           node.label.toLowerCase().includes(i.component.toLowerCase()) ||
102 |           node.id.toLowerCase().includes(i.component.toLowerCase())
103 |       );
104 | 
105 |       if (impact) {
106 |         return { ...node, impactSeverity: impact.severity, impactReason: impact.reason };
107 |       }
108 | 
109 |       return { ...node, impactSeverity: 'SAFE' as const };
110 |     });
111 | 
112 |     return { ...graph, nodes: updatedNodes };
113 |   }
114 | 
115 |   /**
116 |    * Serialize graph to JSON-compatible format for VSIX webview.
117 |    */
118 |   toVisualizationFormat(graph: SystemContextGraph): object {
119 |     return {
120 |       nodes: graph.nodes.map(n => ({
121 |         id: n.id,
122 |         type: n.type,
123 |         label: n.label,
124 |         status: this.getNodeStatus(n),
125 |         impactSeverity: n.impactSeverity,
126 |         impactReason: n.impactReason,
127 |         data: this.summarizeNodeData(n),
128 |       })),
129 |       edges: graph.edges.map(e => ({
130 |         id: e.id,
131 |         source: e.source,
132 |         target: e.target,
133 |         type: e.type,
134 |         label: e.label,
135 |       })),
136 |       generatedAt: graph.generatedAt,
137 |     };
138 |   }
139 | 
140 |   private inferDatabaseNames(svc: ServiceContext): string[] {
141 |     const names: string[] = [];
142 | 
143 |     // From dependencies marked as DATABASE
144 |     const dbDeps = svc.dependencies.filter(d => d.type === 'DATABASE');
145 |     names.push(...dbDeps.map(d => d.targetService));
146 | 
147 |     // Infer from service name if has entities
148 |     if (svc.database.length > 0 && names.length === 0) {
149 |       names.push(svc.identity.name.replace('-service', '') + '_db');
150 |     }
151 | 
152 |     return [...new Set(names)];
153 |   }
154 | 
155 |   private resolveServiceId(targetService: string, services: ServiceContext[]): string | null {
156 |     // Direct match
157 |     const direct = services.find(s => s.identity.serviceId === targetService);
158 |     if (direct) return direct.identity.serviceId;
159 | 
160 |     // Partial match
161 |     const partial = services.find(
162 |       s =>
163 |         s.identity.serviceId.includes(targetService) ||
164 |         targetService.includes(s.identity.serviceId) ||
165 |         s.identity.name.toLowerCase().includes(targetService.toLowerCase()) ||
166 |         targetService.toLowerCase().includes(s.identity.name.toLowerCase())
167 |     );
168 |     if (partial) return partial.identity.serviceId;
169 | 
170 |     return null;
171 |   }
172 | 
173 |   private getNodeStatus(node: GraphNode): string {
174 |     if (node.type === 'DATABASE') return 'database';
175 |     const svc = node.data as ServiceContext;
176 |     return svc.status || 'Unknown';
177 |   }
178 | 
179 |   private summarizeNodeData(node: GraphNode): object {
180 |     if (node.type === 'DATABASE') {
181 |       const db = node.data as DatabaseNodeData;
182 |       return {
183 |         name: db.name,
184 |         tableCount: db.tables.length,
185 |         owner: db.ownerServiceId,
186 |       };
187 |     }
188 | 
189 |     const svc = node.data as ServiceContext;
190 |     return {
191 |       serviceId: svc.identity.serviceId,
192 |       commit: svc.identity.commitHash,
193 |       branch: svc.identity.branch,
194 |       apiCount: svc.apis.length,
195 |       tableCount: svc.database.length,
196 |       dependencyCount: svc.dependencies.length,
197 |       status: svc.status,
198 |       analyzedAt: svc.analyzedAt,
199 |       semanticSummary: svc.semanticSummary,
200 |     };
201 |   }
