  function wrapText(text, maxLen) {
    if (!text) return [''];
    const words = text.split(/[-_\s]+/);
    const lines = [];
    let current = '';
    for (let i = 0; i < words.length; i++) {
      const w = words[i];
      if ((current + ' ' + w).trim().length <= maxLen) {
        current = (current + ' ' + w).trim();
      } else {
        if (current) lines.push(current);
        current = w;
      }
