  window.addEventListener('message', function(e) {
    const msg = e.data;
    if (!msg || typeof msg !== 'object') return;
    if (msg.type === 'update') {
      currentGraph = msg.graph || null;
      currentImpact = msg.impactReport || null;
      render(currentGraph, currentImpact);
