229 |   async incrementalAnalysis(
230 |     discovered: DiscoveredService,
231 |     allServiceIds: string[],
232 |     oldCommit: string
233 |   ): Promise<ServiceContext> {
234 |     const { serviceId, rootPath, commitHash, branch, repository, detectedStack } = discovered;
235 | 
236 |     process.stderr.write(`[BCG] Incremental analysis: ${serviceId} ${oldCommit.slice(0, 7)} → ${commitHash.slice(0, 7)}\n`);
237 | 
238 |     const git = new GitAnalyzer(repository);
239 |     // F02: get ALL changed files in the repo diff, then filter to this service's subdirectory
240 |     const allChangedFiles = git.getChangedFiles(oldCommit, commitHash);
241 | 
242 |     // Compute path prefix of the service relative to the repo root
243 |     const repoRoot = repository;
244 |     const serviceRelPath = path.relative(repoRoot, rootPath).replace(/\\/g, '/');
245 |     const prefix = serviceRelPath ? serviceRelPath + '/' : '';
246 | 
247 |     // Keep only files that belong to this service directory
248 |     const changedFiles = prefix
249 |       ? allChangedFiles.filter(f => f.path.startsWith(prefix))
250 |       : allChangedFiles;
251 | 
252 |     // F07: a DTO change affects the API if the DTO name appears in any endpoint model
253 |     const hasDtoChange = changedFiles.some(f => f.category === 'DTO');
254 |     let dtoAffectsApi = false;
255 |     if (hasDtoChange) {
256 |       const previousContext = this.cache.get(serviceId, branch, oldCommit);
257 |       if (previousContext) {
258 |         const changedDtoNames = changedFiles
259 |           .filter(f => f.category === 'DTO')
260 |           .map(f => path.basename(f.path, '.java').toLowerCase());
261 |         dtoAffectsApi = previousContext.apis.some(api => {
262 |           const reqModel = (api.requestModel ?? '').toLowerCase();
263 |           const resModel = (api.responseModel ?? '').toLowerCase();
264 |           return changedDtoNames.some(dto => reqModel.includes(dto) || resModel.includes(dto));
265 |         });
266 |       }
267 |     }
268 | 
269 |     const changeSet: ChangeSet = {
270 |       serviceId,
271 |       oldCommit,
272 |       newCommit: commitHash,
273 |       changedFiles,
274 |       // F07: DTO change that touches an exposed endpoint counts as API change
275 |       affectsApi: changedFiles.some(f => f.category === 'API') || dtoAffectsApi,
276 |       affectsDatabase: changedFiles.some(f => f.category === 'ENTITY'),
277 |       affectsDependencies: changedFiles.some(f => ['SERVICE', 'CONFIG'].includes(f.category)),
278 |     };
279 | 
280 |     // Get previous context as baseline
281 |     const previousContext = this.cache.get(serviceId, branch, oldCommit);
282 | 
283 |     if (!previousContext) {
284 |       // No baseline - do full analysis
285 |       return this.fullAnalysis(discovered, allServiceIds);
286 |     }
287 | 
288 |     // Build updated context
289 |     const updated: ServiceContext = { ...previousContext };
290 |     updated.identity = { ...previousContext.identity, commitHash, previousCommitHash: oldCommit };
291 |     updated.analyzedAt = new Date().toISOString();
292 |     updated.status = 'Changed';
293 |     updated.detectedStack = detectedStack;
294 | 
295 |     // Re-analyze only affected sections
296 |     if (changeSet.affectsApi && detectedStack === 'spring-boot') {
297 |       process.stderr.write(`[BCG] Re-analyzing APIs for ${serviceId}\n`);
298 |       updated.apis = this.apiParser.parseService(rootPath);
299 |     }
300 | 
301 |     if (changeSet.affectsDatabase && detectedStack === 'spring-boot') {
302 |       process.stderr.write(`[BCG] Re-analyzing DB schema for ${serviceId}\n`);
303 |       updated.database = this.jpaParser.parseService(rootPath);
304 |     }
305 | 
306 |     if (changeSet.affectsDependencies) {
307 |       process.stderr.write(`[BCG] Re-analyzing dependencies for ${serviceId}\n`);
308 |       const otherServices = allServiceIds.filter(id => id !== serviceId);
309 |       const newRestDeps = this.dependencyAnalyzer.analyzeDependencies(rootPath, otherServices);
310 | 
311 |       // F08: Preserve existing DATABASE dependencies and merge new REST deps
312 |       const existingDbDeps = previousContext.dependencies.filter(d => d.type === 'DATABASE');
313 |       const merged = new Map<string, ServiceDependency>();
314 |       for (const dep of [...existingDbDeps, ...newRestDeps]) {
315 |         const key = `${dep.type}:${dep.targetService}`;
316 |         if (!merged.has(key)) merged.set(key, dep);
317 |       }
318 |       // Re-detect database from config in case it changed
319 |       this.mergeDatabaseDependencies(
320 |         Array.from(merged.values()),
321 |         rootPath,
322 |         updated.identity.name,
323 |         updated.database.length > 0,
324 |         merged
325 |       );
326 |       updated.dependencies = Array.from(merged.values());
327 |     }
328 | 
329 |     // Regenerate semantic summary
330 |     if (this.watsonxClient && (changeSet.affectsApi || changeSet.affectsDatabase)) {
331 |       try {
332 |         updated.semanticSummary = await this.watsonxClient.generateServiceSummary(updated);
333 |       } catch {
334 |         // keep old summary
335 |       }
336 |     }
337 | 
338 |     this.cache.set(updated);
339 |     return updated;
340 |   }
