439 |   /**
440 |    * Helper: merge database dependencies from config into a deps array.
441 |    * If a Map is provided, it will be updated in-place; otherwise the array is modified.
442 |    */
443 |   private mergeDatabaseDependencies(
444 |     dependencies: ServiceDependency[],
445 |     rootPath: string,
446 |     serviceName: string,
447 |     hasEntities: boolean,
448 |     mergedMap?: Map<string, ServiceDependency>
449 |   ): void {
450 |     const dbNames = this.dependencyAnalyzer.detectDatabaseUsage(rootPath);
451 |     const addDb = (dbName: string, evidence: string) => {
452 |       const key = `DATABASE:${dbName}`;
453 |       if (mergedMap) {
454 |         if (!mergedMap.has(key)) {
455 |           mergedMap.set(key, { targetService: dbName, type: 'DATABASE', evidence });
456 |         }
457 |       } else {
458 |         if (!dependencies.find(d => d.targetService === dbName)) {
459 |           dependencies.push({ targetService: dbName, type: 'DATABASE', evidence });
460 |         }
461 |       }
462 |     };
463 | 
464 |     for (const dbName of dbNames) {
465 |       addDb(dbName, 'Detected from datasource configuration');
466 |     }
467 | 
468 |     // If no DB from config, infer from entities
469 |     if (hasEntities && !dependencies.find(d => d.type === 'DATABASE') && (!mergedMap || !Array.from(mergedMap.values()).some(d => d.type === 'DATABASE'))) {
470 |       const dbName = serviceName.replace('-service', '') + '_db';
471 |       addDb(dbName, 'Inferred from JPA entities');
