72 |    * F02: Group discovered services by repository so we only read git diff once per repo.
73 |    */
74 |   async analyze(forceRefresh = false): Promise<AnalysisResult> {
75 |     const discovered = await this.scanner.discoverServices();
76 |     const stats = { cached: 0, refreshed: 0, failed: 0 };
77 |     const serviceContexts: ServiceContext[] = [];
78 | 
79 |     const serviceIds = discovered.map(d => d.serviceId);
80 | 
81 |     // F02: build a per-repository HEAD map so all services in the same repo
82 |     // share the same observed commit and we only call git once per repo.
83 |     const repoHeadMap = new Map<string, string>();
84 |     for (const svc of discovered) {
85 |       if (svc.isGitRepo && !repoHeadMap.has(svc.repository)) {
86 |         const git = new GitAnalyzer(svc.repository);
87 |         repoHeadMap.set(svc.repository, git.getHead(false));
88 |       }
89 |     }
90 | 
91 |     for (const svc of discovered) {
92 |       // F02: override commitHash with the authoritative per-repo HEAD
93 |       const repoHead = repoHeadMap.get(svc.repository);
94 |       const effective: DiscoveredService = repoHead
95 |         ? { ...svc, commitHash: repoHead }
96 |         : svc;
97 | 
98 |       try {
99 |         const ctx = await this.analyzeService(effective, serviceIds, forceRefresh);
100 |         serviceContexts.push(ctx);
101 | 
102 |         if (ctx.status === 'Cached') stats.cached++;
103 |         else stats.refreshed++;
104 |       } catch (err) {
105 |         process.stderr.write(`[BCG] Failed to analyze ${svc.serviceId}: ${err}\n`);
106 |         stats.failed++;
107 |         serviceContexts.push(this.makeErrorContext(svc, String(err)));
108 |       }
109 |     }
