42 |   private findServiceDirectories(dir: string, depth: number): string[] {
43 |     if (depth > MAX_DEPTH) return [];
44 | 
45 |     const results: string[] = [];
46 | 
47 |     let entries: fs.Dirent[];
48 |     try {
49 |       entries = fs.readdirSync(dir, { withFileTypes: true });
50 |     } catch {
51 |       return results;
52 |     }
