55 |     const stack = this.detectStack(dir);
56 |     if (stack !== 'unknown' && !this.isMavenAggregator(dir)) {
57 |       results.push(dir);
58 |       // For Spring Boot, do NOT recurse further into this service directory
59 |       if (stack === 'spring-boot') return results;
60 |     }
