411 | /**
412 |  * F23: Strict service resolver — reject ambiguous short names.
413 |  * Returns the matched service or throws McpError with candidate list.
414 |  */
415 | function resolveService(serviceArg: string, services: typeof cachedResult extends null ? never : NonNullable<typeof cachedResult>['services']): NonNullable<typeof cachedResult>['services'][number] {
416 |   // 1. Exact canonical ID match
417 |   const exactId = services.find(s => s.identity.serviceId === serviceArg);
418 |   if (exactId) return exactId;
419 | 
420 |   // 2. Exact name match
421 |   const exactName = services.find(s => s.identity.name === serviceArg);
422 |   if (exactName) return exactName;
423 | 
424 |   // 3. Unique prefix/substring match — only if unambiguous
425 |   const partialMatches = services.filter(
426 |     s =>
427 |       s.identity.serviceId.includes(serviceArg) ||
428 |       s.identity.name.includes(serviceArg)
429 |   );
430 | 
431 |   if (partialMatches.length === 1) return partialMatches[0];
432 | 
433 |   if (partialMatches.length > 1) {
434 |     const candidates = partialMatches.map(s => s.identity.serviceId).join(', ');
435 |     throw new McpError(
436 |       ErrorCode.InvalidParams,
437 |       `Ambiguous service name "${serviceArg}". Matching candidates: [${candidates}]. Please use an exact service ID.`
438 |     );
439 |   }
440 | 
441 |   const available = services.map(s => s.identity.serviceId).join(', ');
442 |   throw new McpError(
443 |     ErrorCode.InvalidParams,
444 |     `Service "${serviceArg}" not found. Available: [${available}]`
445 |   );
446 | }
