    if (basename.endsWith('controller.java')) return 'API';
    if (lower.includes('/controller/')) return 'API';
    if (basename.endsWith('entity.java')) return 'ENTITY';
    if (lower.includes('/entity/') || lower.includes('/entities/')) return 'ENTITY';
