          const rawPath = line.slice(3).split(' -> ').pop()!.trim();
          const changeType = xy.includes('D') ? 'deleted' : xy.includes('A') || xy.trim() === '??' ? 'added' : 'modified';
          return { path: rawPath, category: this.classifyFile(rawPath), changeType } as ChangedFile;
